"""The checks ledger — generated by code, never written by a role.

Every plan row and every test lands in EXACTLY ONE state. The count of rows equals the
count of plan rows plus the count of manifest tests: an unlisted row would read as passed,
which is the single most expensive lie a test report can tell (design section 6).

Inputs: test-plan.md, automation-manifest.json, run-report.json, triage.json,
context-manifest.json (open subtasks) and the gate decisions in pipeline.json /
state/journal.jsonl. Outputs: work/ledger.json and work/ledger.md.

`delivery_ready` and `reasons` are NOT decided here — check_delivery.py fills them in.
This script only states what happened to each row.

Usage: ledger.py <artifacts-dir> [--json] [--print]
"""
import argparse
import json
import os
import sys
from datetime import datetime, timezone
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))

import acceptance as AC  # noqa: E402  (the ONE reader of "red by the requirement": `red_by_requirement`, AR-13)
import contract as C  # noqa: E402
import proof_level as PL  # noqa: E402
from event_store import atomic_json  # noqa: E402

DONE_SUBTASK_STATUSES = {"done", "closed", "resolved", "completed"}
# What a test row's `proof_level` says when there is no level id to say it with. A row that
# reached a level carries the level's own id (`references/verification-levels.json`); `None` is
# "probed by nobody" (a required check that is absent); these two are the other honest answers.
# The ledger state of a case the person took over (a handed test, a manual-human case with its package). It is inside
# the existing vocabulary on purpose: `not_executed` is exactly what happened and the suffix says why, so a reader of
# an older ledger and a reader of this one mean the same thing by the same word. `check_delivery` re-exports it.
HANDED_STATE = "not_executed:handed_to_person"
# HF2-3 (3c1): the ledger state of a case whose OWN runs are green while a Then of it stands behind another case's red
# assert in the same test (a `blocked_by_check` row, or a covered Then of a test that stopped at that red). Inside the
# vocabulary like HANDED_STATE; its kind is `blocked_by_check` in `references/delivery-verdict-kinds.json`.
BLOCKED_STATE = "not_executed:" + C.BLOCKED_BY_CHECK
# What a manifest test the run has no result row for reads (HF2-6): the ONE spelling the ledger state
# `not_executed:<this>` and the trace table's `not run` basis share. Never a `passed_green`, never a `pass`.
NO_RUN_RESULT = "no result for this test in run-report.json"
# HF2-11 (11c): the ledger state of a test whose green run ran OTHER code than the test holds now (an edit, or a helper
# it uses, after the run). Inside the vocabulary like HANDED_STATE; its kind is `changed_unrun` in
# `references/delivery-verdict-kinds.json`. A green of other code is not a pass of this code.
CHANGED_STATE = "not_executed:changed_since_run"
UNVERIFIED = "unverified"             # the critic's own word for "could not verify" (D-0013)
PROOF_NOT_REQUIRED = "not_required"  # an unchanged, reused test: nothing was asked of it (D-0012)
PROOF_UNKNOWN = "unknown"             # its test file cannot be found, so no receipt can be compared (FR-41)


def _unknown_run_word(word) -> bool:
    """HF3-7 (M3, F-5 (b)): is `word` a run result word outside the vocabulary the contract knows (`C.RUN_WORDS_KNOWN`)?
    The ONE classifier of both ledger sites (`test_state`, `plan_row_state`) - the vocabulary is derived from the contract, not
    a third literal (AR-1). A word nobody recorded (`""`, None) is no word at all - that is "no result", not an unknown one.
    The answer errs toward "unknown", i.e. toward NOT reading a green: the word is read as `result_status` reads it."""
    text = C.result_status({"status": word})   # the ONE normalization (AR-13): strip + lower + alias; a falsy value is no word
    return bool(text) and text not in C.RUN_WORDS_KNOWN


def _run_word_text(word) -> str:
    """A recorded word (a run word, a review verdict) as a ledger state may print it: no backtick (`check_delivery` reads
    "is `<state>`") and one line."""
    return " ".join(str(word).replace("`", "'").split())


def _decided_reason(reason: str) -> str:
    """`deferred_by_decision:gateA` -> the ledger state `deferred_by_decision`."""
    return "deferred_by_decision" if C.unresolved_decided(reason) else str(reason or "")


# P20 (t-227c): the reason of a `then_bindings` row whose Then has no expected value anybody
# confirmed - an `unknown` oracle with an open question. It is the ONE spelling every reader of the
# gap shares (manifest_from_tests writes it, traceability and this ledger read it, the report lists
# it). It is NOT a `deferred_by_decision`: that word prints "a person's recorded decision", which
# is false for a question nobody answered (FR-41). The ledger state it makes does not block
# delivery (F7): a check that was not executed is a gap in the report, not a found discrepancy.
# The word has ONE home, `contract.EXPECTATION_UNCONFIRMED` (it is in `UNRESOLVED_REASONS`, FR-13); this
# name stays for the readers that import it from here.
EXPECTATION_UNCONFIRMED = C.EXPECTATION_UNCONFIRMED
NOT_VERIFIED_UNCONFIRMED = "not_verified:" + EXPECTATION_UNCONFIRMED
GREEN_ON_UNCONFIRMED = "the green run proves only that the implementation does what it does"


def green_on_open_words(oracle: dict) -> str:
    """What a person reads for a Then whose test is GREEN while the resolver reads its expected value `open`
    or `invalid` (t-269 F2): the value nobody confirmed was checked against the implementation itself, so
    the green proves nothing about the requirement. One sentence for the ledger and the traceability table
    (FR-10). `oracle` is a `contract.resolve_then_oracle` reading."""
    ref = str((oracle or {}).get("ref") or "").strip()
    if (oracle or {}).get("state") == "invalid":
        head = f"expected value unconfirmed (its source '{(oracle or {}).get('source')}' is not an oracle word)"
    else:
        head = f"expected value unconfirmed ({ref} open)" if ref else "expected value unconfirmed (no question is named)"
    return f"{head} — {GREEN_ON_UNCONFIRMED}"


def open_oracles(artifacts: Path, cases: dict) -> dict:
    """{case id: {Then number: `resolve_then_oracle` reading}} for the Thens whose expected value the ONE
    resolver reads `open` or `invalid` (an `unknown` oracle nobody settled, an invented word). A case with no
    `then_oracles` line (written before t-227) has no entry: nothing is read for it, so a legacy story reads
    exactly as it did. Never raises on a story's own data (P1): a case it cannot read has no entry."""
    out: dict = {}
    questions = None
    try:
        from traceability import question_rows, then_oracle_states
    except Exception:
        return out
    for cid, meta in (cases or {}).items():
        try:
            text = C.read_text(Path(meta["path"])) if isinstance(meta, dict) and meta.get("path") else ""
            entries, _problem = C.then_oracles_from_text(text)
            if not entries:
                continue
            if questions is None:
                questions = question_rows(artifacts)
            gaps = {s["then"]: s for s in then_oracle_states(text, questions)
                    if s.get("state") != "settled" and isinstance(s.get("then"), int)}
        except Exception:
            continue
        if gaps:
            out[cid] = gaps
    return out


def unconfirmed_bindings(manifest: dict, case: str, cfg=None) -> list:
    """The `then_bindings` rows of ONE case that say `expectation_unconfirmed`. A case spelled with
    or without its area matches (`contract.case_matches`); a legacy manifest has no such row, so
    every reader that asks gets `[]` and behaves as it did before t-227."""
    out = []
    for row in manifest.get("then_bindings") or []:
        if (isinstance(row, dict) and str(row.get("reason") or "") == EXPECTATION_UNCONFIRMED
                and str(row.get("status") or "") != "covered"
                and C.case_matches(str(row.get("case") or ""), case, cfg=cfg)):
            out.append(row)
    return out


def unconfirmed_detail(pending: list) -> str:
    """What the ledger row says of the unconfirmed Thens: which Then, which question, the value the
    test saw (`observed: not recorded` when the test never reached it), and what is wanted of the
    person - in the task's own terms (FR-20), no ledger shorthand."""
    parts = []
    for case, row in pending:
        seen = row.get("observed")
        seen = "" if seen is None else " ".join(str(seen).split())
        question = str(row.get("question") or "").strip()
        parts.append(f"{case} Then {row.get('then')}: expected value unconfirmed, observed: {seen or 'not recorded'}"
                     + (f". Needed: your answer to {question}" if question else ""))
    return "; ".join(parts)


def _whole_case_unconfirmed(manifest: dict, cases: list) -> list:
    """What the ledger says of a WHOLE-case `unresolved[]` row whose reason is `expectation_unconfirmed`: the
    case, the question it names and the value seen, in the task's own terms. Same sentence shape as
    `unconfirmed_detail`; the row has no Then number, the case as a whole waits for the person."""
    parts = []
    for u in C.manifest_unresolved(manifest):
        case = str(u.get("case") or "")
        # D2-B3 (AR-13): by the identity match, not the raw `in` (a bare row against an area case is the same case; a blank
        # row case names nothing, two different areas are two cases)
        if (str(u.get("reason") or "") != EXPECTATION_UNCONFIRMED or not case.strip()
                or not C.names_case(cases, case)):
            continue
        question = str(u.get("question") or "").strip()
        seen = u.get("observed")
        seen = "" if seen is None else " ".join(str(seen).split())
        parts.append(f"{case}: expected value unconfirmed, observed: {seen or 'not recorded'}"
                     + (f". Needed: your answer to {question}" if question else ""))
    return parts


# --- HF2-3 (3c1): a case whose own runs are green beside a red it does not own --------------------------------------
# TP1-12586: ONE test covers TC-004, TC-005 and TC-006 and stops at TC-004's Then 2. The unit is the (Then, instance)
# pair (AR-26): TC-005 and TC-006 have green tests of their own, and the Thens they hold on the stopped test were never
# executed - so they read "not executed behind another check", never `failed` (the red is TC-004's: FR-20, FR-34) and
# never `passed_green` (FR-58, FR-59).

def _blocked_rows(manifest: dict, cfg=None, triage=None, report=None) -> list:
    """The `blocked_by_check` Thens of `manifest` (`contract.then_remainders`); [] when it holds none (no config read).
    With `triage` and `report` (R6, t-1508) the Thens the current triage names as waiting join them - the same list the
    delivery check reads; without them, the manifest's rows alone."""
    rows = manifest.get("then_bindings") if isinstance(manifest, dict) else None
    from_manifest = isinstance(rows, list) and any(isinstance(b, dict) and b.get("reason") == C.BLOCKED_BY_CHECK for b in rows)
    if not from_manifest and (triage is None or report is None):
        return []
    return C.then_remainders(manifest, cfg, reasons=(C.BLOCKED_BY_CHECK,), triage=triage, report=report)


def diagnostic_words(row) -> str:
    """The words a Then behind a red takes from its row's diagnostic run (`contract.triage_blocked_rows` carries
    `diagnostic`: `{evidence, outcome}`), `""` for a row without one: `; a diagnostic run without the red assert showed
    Then <n> <held|red> (<evidence path>)`, or `; a diagnostic run without the red assert was made (<path>)` when the
    run named no outcome for this Then. ONE sentence for the ledger detail and the "Left with you" line."""
    block = row.get("diagnostic") if isinstance(row, dict) else None
    if not isinstance(block, dict) or not block.get("evidence"):
        return ""
    if block.get("outcome") in ("held", "red"):
        return (f"; a diagnostic run without the red assert showed Then {row.get('then')} {block['outcome']} "
                f"({block['evidence']})")
    return f"; a diagnostic run without the red assert was made ({block['evidence']})"


def red_instances(manifest: dict, report: dict) -> dict:
    """`{instance id: [the unresolved[] rows that make it red]}` over EVERY instance of the story: THE one call of
    `acceptance.red_by_requirement` on the ledger's path (AR-13), its source the report's CURRENT result (v-a) - a green
    current result is not red whatever the manifest says. Empty when no `contradicts_requirement` row matches or the
    manifest or the report cannot be read: nothing is red, and a case is read by its own runs (FR-59)."""
    scope = AC.story_scope(manifest)
    ids = list(dict.fromkeys(i for members in scope.values() for i in members))
    return AC.red_by_requirement(manifest, [{"instance_id": i} for i in ids], scope, report=report)


def _shadowed(manifest: dict, red: dict, blocked: list, cases: list, cfg=None) -> dict:
    """E(C) per case of the row: `{case: [{iid, names, rows, blocked, covered}]}`, only the cases that have one. An
    instance I is in E(C) when ALL hold: I is red (`red`); I is NOT red by a row of C itself (`acceptance.red_by_own_row`
    - a case's own row never hides its own bug, N1); and the manifest binds I to C - a `blocked_by_check` row of C
    whose `instance_id` is one of I's names, or a covered binding of I to C. An instance red for C's neighbour with NO
    binding to C is not in E(C): C keeps the `failed` that instance gives it (the unknown never makes C green)."""
    if not red:
        return {}
    covered = [b for b in manifest.get("then_bindings") or [] if isinstance(b, dict) and str(b.get("status") or "") == "covered"] \
        if isinstance(manifest.get("then_bindings"), list) else []
    tests = {C.test_instance_id(t): t for t in C.manifest_tests(manifest)}
    out: dict = {}
    for case in cases:
        for iid, rows in red.items():
            entry = tests.get(iid)
            if entry is None or AC.red_by_own_row(red, iid, case, cfg):
                continue
            names = list(dict.fromkeys([iid, *C.instance_id_aliases(entry, cfg)]))
            held = [r for r in blocked if r["instance_id"] in names and C.case_matches(r["case"], case, cfg=cfg)]
            bound = [b for b in covered if str(b.get("instance_id") or "").strip() in names
                     and C.case_matches(str(b.get("case") or ""), case, cfg=cfg) and C.then_number(b.get("then"))]
            if held or bound:
                out.setdefault(case, []).append({"iid": iid, "names": names, "rows": rows, "blocked": held, "covered": bound})
    return out


def behind_red(manifest: dict, report: dict, case: str, cfg=None) -> tuple:
    """`(covered Thens, blocker cases)` of `case` where a red instance it is bound to hides it (R1, HF2-0): the Then numbers
    of the COVERED bindings of `case` on the instances in E(C) (`_shadowed` - the ONE reader, not a second one), ascending,
    and the cases those instances are red for (`blocker_cases`, no instance id). `([], [])` when nothing is red for another
    case or `case` has no binding to a red instance - the caller reads the case as it did before. Shape B (the Thens moved
    before the red assert) has no `blocked_by_check` row, so these are the only Thens its "Left with you" line can name."""
    red = red_instances(manifest, report)
    records = _shadowed(manifest, red, _blocked_rows(manifest, cfg), [case], cfg).get(case, [])
    thens = sorted({C.then_number(b.get("then")) for rec in records for b in rec["covered"]})
    blockers = list(dict.fromkeys(c for rec in records for c in blocker_cases(rec["iid"], manifest, red, cfg)))
    return thens, blockers


def _case_status_without(report: dict, case: str, excluded, cfg=None) -> str:
    """The run status of `case` as `contract.run_results` projects it, with the current results of the instances named in
    `excluded` (every spelling each answers to) left out: the case read by ITS OWN runs when a sibling instance is red for
    another case's requirement. Nothing excluded -> `run_results(report).get(case)` byte for byte. "" when no run of the
    case remains (the caller says whether that is "no result" or "behind a red"). The leaving-out is done on a copy of the
    report (`current_results`, else `results`) so the projection stays `run_results`' own and no grouping rule is written
    twice. A report that is no object reads as no run at all."""
    if not isinstance(report, dict):
        return ""
    names = {str(n) for n in excluded or ()}
    key = "current_results" if isinstance(report.get("current_results"), list) else "results"
    if not names or not isinstance(report.get(key), list):
        return C.case_lookup(C.run_results(report, cfg), case, cfg, exact_wins=False) or ""
    kept = [row for row in report[key] if not (isinstance(row, dict) and str(
        row.get("instance_id") or row.get("test_instance_id") or C.test_instance_id(row)).strip() in names)]
    return C.case_lookup(C.run_results(dict(report, **{key: kept}), cfg), case, cfg, exact_wins=False) or ""


def _status_without_shadow(report: dict, case: str, shadow: dict, cfg=None) -> str:
    """`_case_status_without` for the instances E(C) of `case` holds (`shadow`)."""
    return _case_status_without(report, case, [n for rec in shadow.get(case, []) for n in rec["names"]], cfg)


def blocker_cases(name: str, manifest: dict, red: dict, cfg=None) -> list:
    """The cases a `blocked_by_check` row's `blocking_check` stands for, in the task's own terms (D8): a case key is that
    case; an instance id (any spelling of a manifest test) is NEVER printed - it stands for the cases whose rows make that
    instance red (`red`, `red_instances`), possibly none; an empty name stands for none. The ONE reader of the word: the
    ledger detail and the delivery check's "Left with you" line both print what it returns."""
    for entry in C.manifest_tests(manifest):
        if name in C.instance_id_aliases(entry, cfg):
            rows = red.get(C.test_instance_id(entry)) or []
            return list(dict.fromkeys(c for c in (str(r.get("case") or "").strip() for r in rows) if c))
    return [name] if name else []


def _stopped_at(rows: list) -> str:
    """Where the test stopped, in the words of the red rows: `<R> Then <m>` per row (`thens` of the row; none readable ->
    the case alone, no number is invented), rows joined by `and`."""
    out = []
    for row in rows:
        raw = row.get(C.UNRESOLVED_THENS_KEY)
        numbers = sorted({n for n in (C.then_number(x) for x in raw) if n}) if isinstance(raw, list) else []
        case = str(row.get("case") or "").strip()
        out.append(f"{case} Then {', '.join(str(n) for n in numbers)}" if numbers else case)
    return " and ".join(dict.fromkeys(out))


def _behind_words(manifest: dict, report: dict, red: dict, shadow: dict, blocked: list, cases: list, cfg=None) -> list:
    """One sentence per Then of `cases` that stands behind a red (variant FA-11 (b), FB-2 (a)), by case and Then number:
      a `blocked_by_check` Then:  `<C> Then <n>: behind <case of the blocker>` + `; its other Thens passed` ONLY when the
        case's OWN run passed (`_status_without_shadow`: its runs outside E(C), the red instance left out); a case with no
        run of its own, or whose own run failed, errored or is anything but passed, has nothing that passed to say (FR-41);
      a covered Then of C on a red instance I:  `<C> Then <n>: not proven - the test stopped at <R> Then <m>`
        (`<R>` alone when R's row names no Then).
    A `blocked_by_check` row whose blocker is no longer red (the instance is not in E(C)) is read as it stands - the Then
    is still not executed: a stale row never turns into a pass. No instance id is printed (D8). [] when there is none."""
    out = []
    for case in cases:
        passed = _status_without_shadow(report, case, shadow, cfg) in ("passed", "pass")
        found = [(r["then"], f"{case} Then {r['then']}: behind "
                             f"{' and '.join(blocker_cases(r['blocking_check'], manifest, red, cfg)) or 'another check'}"
                             + ("; its other Thens passed" if passed else "") + diagnostic_words(r))
                 for r in blocked if C.case_matches(r["case"], case, cfg=cfg)]
        for rec in shadow.get(case, []):
            # FA-11 (a) would plug in HERE (owner's word pending, NOT built): a covered Then of the stopped test would read
            # `passed` only when the failure site lies inside the red Then's range and strictly after this Then's range.
            # Variant (b), the safe default: every covered Then of C on a red instance is not proven.
            found += [(C.then_number(b.get("then")), f"{case} Then {C.then_number(b.get('then'))}: not proven - the test "
                                                     f"stopped at {_stopped_at(rec['rows'])}") for b in rec["covered"]]
        out += [text for _, text in sorted(found, key=lambda pair: pair[0])]
    return out


def _reason_branch_rank(reason: str) -> int:
    """The position of a `unresolved[]` reason among the branches of `plan_row_state`'s loop (the order of those branches IS
    the contract): the person's debt first (it only records and goes on), then a decided deferral, `pending_implementation`,
    `blocked_by_env`, `impossible`, and last every reason that is read against the run (hand-off, contradicts, the rest)."""
    if reason == EXPECTATION_UNCONFIRMED:
        return 0
    if C.unresolved_decided(reason):
        return 1
    return {"pending_implementation": 2, "blocked_by_env": 3, "impossible": 4}.get(reason, 5)


def _reasons_of_case(rows: list, case: str, cfg) -> list:
    """RD1-2 (S-6): the reasons of every `unresolved[]` row that names `case` by `contract.case_matches`, in branch order
    (stable: the manifest's own order inside one rank). A blank case or a blank row key matches nothing (E-B1)."""
    if not str(case or "").strip():
        return []
    found = [reason for key, reason in rows if str(key or "").strip() and C.case_matches(key, case, cfg=cfg)]
    return sorted(found, key=_reason_branch_rank)


# --- proof strength: the sides a proof met (t-2181 §2.3, PC-5; C9; B1, B2, S12) ------------------------------------------
# The two ledger states of the §2.3 branch of `plan_row_state` (kinds `sides_unknown` and `on_substitute` of
# `references/delivery-verdict-kinds.json`). Neither is ever `passed_green`, neither blocks delivery by itself (`after_checks`).
SIDES_UNKNOWN_STATE = "not_verified:sides_unknown"
ON_SUBSTITUTE_STATE = "not_verified:on_substitute"
# t-2277 J-C7 (PC-5 fix round, L1): a Then whose green rests on a placeholder locator the first look marked and nobody settled with a run.
# Like the two above it is `after_checks` and never `passed_green`; the kind owner is the PRODUCT (J-C5 `blocked_by: product`, FR-19, FR-46).
# Every `not_verified:*` state needs its OWN exact row in `references/delivery-verdict-kinds.json` `ledger_states`: the prefix row
# `not_verified` reads kind `decided_elsewhere` (verdict `none`), so a state without its row counts as no debt at all
# (`test_sides_ledger.every_not_verified_state_of_the_proof_branches_has_its_own_kind` reads these constants).
PLACEHOLDER_OPEN_STATE = "not_verified:placeholder_open"
_REAL = "real"      # the one reality word the ledger acts on; every other word (and a missing key) reads "not real"
_UNREADABLE_STAMP = "the record of the sides it met could not be read"


def _met_real(test_sides, stamp: dict, side: str) -> bool:
    """Did this proof meet `side` for real? True only when `real` stands in BOTH the test's declaration (`tests[].sides`) AND the
    proof's stamp (`sides_met`): a missing key, a non-object declaration or stamp, a word other than `real` is NOT real (B1,
    AR-28). `stamp` is the row (or block) carrying `sides_met`. ERROR DIRECTION: over-caution only (`on_substitute` for a Then
    really proven, costing a re-pass line); never `real` for a side nobody recorded as real."""
    met = stamp.get("sides_met") if isinstance(stamp, dict) else None
    return (isinstance(test_sides, dict) and test_sides.get(side) == _REAL
            and isinstance(met, dict) and met.get(side) == _REAL)


def _resolved_about(about, test_sides, stamp: dict) -> list:
    """The sides a Then speaks about, resolved (B1): `about` when it names at least one side (a bare string is one side), else the
    keys of the test's own `sides` UNION every side the stamp recorded with a reality other than `real`. By construction an
    empty result occurs only when the stamp holds no non-real side, so an empty claim never proves on a substitute. `about: []`,
    an absent `about` and an `about` of another type all fall to the union (never to "nothing to check")."""
    named = [about] if isinstance(about, str) else about if isinstance(about, list) else []
    named = [str(side).strip() for side in named if str(side).strip()]
    if named:
        return list(dict.fromkeys(named))
    declared = list(test_sides) if isinstance(test_sides, dict) else []
    met = stamp.get("sides_met") if isinstance(stamp, dict) else None
    recorded = [side for side, reality in met.items() if reality != _REAL] if isinstance(met, dict) else []
    return list(dict.fromkeys(str(side) for side in [*declared, *recorded]))


def _sides_applicable(row: dict, test: dict | None) -> bool:
    """Does the §2.3 branch read this proof at all (E-T1)? Only a result row that carries a stamp, or whose test declares a
    value other than `real` in `tests[].sides`; every other row is read exactly as before the branch existed."""
    declared = test.get("sides") if isinstance(test, dict) else None
    return (isinstance(row, dict) and ("sides_met" in row or "sides_unknown" in row)) or (
        isinstance(declared, dict) and any(reality != _REAL for reality in declared.values()))


def _green(row) -> bool:
    return isinstance(row, dict) and C.result_status(row) in ("passed", "pass")


def _proof(row: dict, entry, about) -> tuple:
    """`(proven, unknown, sides that were not real, why unknown)` of ONE green row of one test. A row whose `sides_met` is present
    and is not an object is UNKNOWN, like `sides_unknown` (B2, AR-28/FR-59): a record that cannot be read is never a pass, even when
    the test declares nothing (an empty claim proves only when the stamp holds no non-real side, and a stamp that is no object
    holds nothing readable)."""
    if not _sides_applicable(row, entry):
        return True, False, [], ""
    if "sides_unknown" in row:
        return False, True, [], ""
    if "sides_met" in row and not isinstance(row.get("sides_met"), dict):
        return False, True, [], _UNREADABLE_STAMP
    declared = entry.get("sides") if isinstance(entry, dict) else None
    bad = [s for s in _resolved_about(about, declared, row) if not _met_real(declared, row, s)]
    return not bad, False, bad, ""


REAL_CODE = "real code"
REAL_OR_MOCK_UNKNOWN = "real or mock: not established"
KEPT_BY_DECISION_WORDS = "kept by the person's decision"
SUBSTITUTED_WORDS = "the side was substituted"
DATE_NOT_RECORDED = "(date not recorded)"
MOCK_LEAD = "on a mock:"
REAL_OR_MOCK_MARKS = (REAL_CODE, MOCK_LEAD, REAL_OR_MOCK_UNKNOWN)   # the words a test line of the report may carry: the ONE list (F4), imported by the report check
_WHAT_MAX = 60


def real_or_mock(entry, run_row, prov: dict) -> str:
    """The words that say whether ONE test's result was obtained on real code or on a mock (t-2277 W3, owner 11.11.2026: "always visible,
    on a mock or on real code"; a green stays green, only the words change). ONE producer (AR-15): the report's per-test lines and the
    scribe's `Left with you` items read the ledger test row's `real_or_mock`, which is this. Data only (AR-29): the test's own `sides`
    declaration, the run row's proof stamp (`sides_met`, `sides_unknown`: `_proof`, the one reading of them) and the manifest's
    `provisional[]` rows (`prov` = `contract.manifest_provisional`):
      - a `kept_by_decision` row among the test's `provisional` ids -> `on a mock: <side> — kept by the person's decision <date>`; the
        date is the row's `decided_at` when it carries one, else `(date not recorded)`, never a guessed one (FR-41);
      - a side the test declares, or the stamp records, that is not `real` (`_proof`'s `bad`), and no kept row covers it -> `on a mock: <side> —
        the side was substituted`; several sides list each;
      - an unreadable stamp, `sides_unknown`, a `provisional` field of the test that could not be read, or a P-n the test names that no
        readable row answers (a dangling id, a manifest-level skip) -> `real or mock: not established` (AR-28: an unknown is never `real code`);
      - none of them -> `real code`. A story with no `pipeline.sides` record has no stamp and no declared side, so every test reads
        `real code`: there that is the default of an unrecorded story, the same rule as `_proof`'s legacy branch, not a recorded fact (N2).
    "" when the test has no run row (no result, nothing to mark). Never raises over data."""
    if run_row is None:
        return ""
    iid = C.test_instance_id(entry) if isinstance(entry, dict) else ""
    _, unknown, bad, _why = _proof(run_row, entry, None)
    skipped = [s for s in prov.get("skipped") or [] if iid and str(s).startswith(f"tests[] {iid}:")]
    rows = {C.provisional_id(r): r for r in prov.get("rows") or []}
    named = (prov.get("by_test") or {}).get(iid, [])
    skipped += [p for p in named if p not in rows]
    kept = [rows[p] for p in named if p in rows and str(rows[p].get("status") or "") == "kept_by_decision"]
    parts, covered = [], set()
    for row in kept:
        side = str(row.get("settles_on") or "").strip()
        what = " ".join(str(row.get("what") or "").split())
        what = (what[:_WHAT_MAX].rstrip() + "...") if len(what) > _WHAT_MAX else what
        label = side or what or "a call"
        when = " ".join(str(row.get("decided_at") or "").split()) or DATE_NOT_RECORDED
        parts.append(f"{MOCK_LEAD} {label}" + (f" ({what})" if what and side else "") + f" — {KEPT_BY_DECISION_WORDS} {when}")
        covered.add(side)
    parts += [f"{MOCK_LEAD} {side} — {SUBSTITUTED_WORDS}" for side in bad if side not in covered]
    if unknown or skipped:
        parts.append(REAL_OR_MOCK_UNKNOWN)
    return "; ".join(parts) if parts else REAL_CODE


def _case_rows(index: dict, case: str, cfg) -> list:
    """The green current rows of `case` that the run recorded, joined to a manifest test or not (a legacy row names its case only)."""
    seen, out = set(), []
    for row in index["rows"].values():
        if id(row) not in seen and _green(row) and (C.case_matches(str(row.get("case") or ""), case, cfg=cfg)
                                                    or C.names_case(C.manifest_test_links(row, cfg), case, cfg)):
            seen.add(id(row))
            out.append(row)
    return out


def _proof_index(manifest: dict, report: dict, cfg) -> tuple:
    """`(tests, entry_of, index, entry_of_row, run_row_for)` - the ONE join of a run row to its manifest test is `case_stamp.run_row_for` (AR-13,
    HF2-6): exact id first, then the dashboard's tolerant rule, then the legacy single row of a case. `entry_of(iid)` is the test a
    binding names (the instance id or one of its aliases); `entry_of_row(row)` is the reverse of the join, None for a row no test joins."""
    import case_stamp as CS   # lazy: the stamp's own imports must not load with the ledger
    from traceability import is_dead_test   # lazy: traceability imports this module
    tests = [t for t in C.manifest_tests(manifest) if isinstance(t, dict)]
    index = CS.run_rows_index(C.current_instance_results(report), [t for t in tests if not is_dead_test(t)], cfg)
    owner: dict = {}
    for entry in tests:
        row = CS.run_row_for(entry, index)
        if row is not None:
            owner.setdefault(id(row), entry)

    def entry_of(iid: str):
        return next((t for t in tests if iid and iid in {C.test_instance_id(t), *C.instance_id_aliases(t, cfg)}), None)

    return tests, entry_of, index, lambda row: owner.get(id(row)), CS.run_row_for


def _sides_units(manifest: dict, report: dict, cases: list, cfg) -> list:
    """The units of the §2.3 branch, `[{label, case, then, found}]` with `found` = `[_proof(...)]`. One UNIT per covered Then of a case
    (a Then proven by SEVERAL tests is proven when ANY one test proves it on its own: the evidence of two tests is never merged,
    FR-18), one per walked manual case, and - for a case with no covered Then binding at all - one per case (`then` None).
    A covered Then reads the green rows its bound instances JOIN (`case_stamp.run_row_for`); when none of them has a green joined row
    the unit is NEVER dropped (B1): it reads the case's own green rows, one by one, with the binding's `about` (a legacy row that
    joins nothing, a row of a test no binding names). A walk that has a `sides_met` which is no object is unknown (B2)."""
    covered = [b for b in manifest.get("then_bindings") or [] if isinstance(b, dict) and str(b.get("status") or "") == "covered"]
    _, entry_of, index, entry_of_row, run_row_for = _proof_index(manifest, report, cfg)
    units = []
    for case in cases:
        mine = [b for b in covered if C.case_matches(str(b.get("case") or ""), case, cfg=cfg) and C.then_number(b.get("then"))]
        case_rows = _case_rows(index, case, cfg)
        for number in sorted({C.then_number(b.get("then")) for b in mine}):
            group = [b for b in mine if C.then_number(b.get("then")) == number]
            found = []
            for b in group:
                entry = entry_of(str(b.get("instance_id") or "").strip())
                row = run_row_for(entry, index) if entry is not None else None
                if _green(row):
                    found.append(_proof(row, entry, b.get("about")))
            if not found:       # no bound instance has a green joined row: the case's green rows are the Then's proofs (B1)
                found = [_proof(row, entry_of_row(row), b.get("about")) for b in group for row in case_rows]
            if found:
                units.append({"label": f"{case} Then {number}", "case": case, "then": number, "found": found})
        if not mine:        # no covered Then to read: the case's own green tests, each with an empty claim (resolved by the union)
            found = [_proof(row, entry_of_row(row), None) for row in case_rows]
            if found:
                units.append({"label": case, "case": case, "then": None, "found": found})
        for walk in report.get("current_manual_checks") if isinstance(report.get("current_manual_checks"), list) else report.get("manual_checks") or []:
            if not (isinstance(walk, dict) and C.case_matches(str(walk.get("case") or ""), case, cfg=cfg)
                    and C.result_status({"status": walk.get("result")}) in ("passed", "pass")):
                continue
            if not _sides_applicable(walk, None):
                continue
            # manual-agent rule (B2): the walk's `about`, else every side its stamp records; proven when each is `real` in the stamp
            # (no test declaration exists for a walk). A walk that records `sides_unknown`, or whose stamp is no object, is unknown.
            if "sides_met" in walk and not isinstance(walk.get("sides_met"), dict):
                units.append({"label": f"{case} (walked)", "case": case, "then": None, "found": [(False, True, [], _UNREADABLE_STAMP)]})
                continue
            met = walk.get("sides_met") if isinstance(walk.get("sides_met"), dict) else {}
            bad = [s for s in _resolved_about(walk.get("about"), None, walk) if met.get(s) != _REAL]
            units.append({"label": f"{case} (walked)", "case": case, "then": None,
                          "found": [(not bad and "sides_unknown" not in walk, "sides_unknown" in walk, bad, "")]})
    return units


def _unit_state(unit: dict):
    """The state of ONE unit no proof proves: `sides_unknown` when any green proof of it is unknown, else `on_substitute`; None when
    some proof proves it."""
    found = unit["found"]
    if any(proven for proven, _, _, _ in found):
        return None
    return SIDES_UNKNOWN_STATE if any(unknown for _, unknown, _, _ in found) else ON_SUBSTITUTE_STATE


def _unit_words(unit: dict) -> str:
    """`<label>: <sides that were not real>` (or the reason the record was unreadable), the detail of one unit."""
    sides = list(dict.fromkeys(s for _, _, bad, _ in unit["found"] for s in bad))
    why = next((why for _, unknown, _, why in unit["found"] if unknown and why), "")
    return unit["label"] + (": " + ", ".join(sides) if sides else f": {why}" if why else "")


def _sides_reading(manifest: dict, report: dict, cases: list, cfg) -> tuple:
    """`(state, detail)` of the §2.3 branch for the cases of one plan row whose runs are ALL green by now, or None when the branch
    reads nothing (every proof is proven, or none of them is stamped or declares a non-real side). A unit (`_sides_units`) that no
    proof proves reads `sides_unknown` when any green proof of it is unknown, else `on_substitute`; the row reads the weakest unit
    (E-O1), `sides_unknown` before `on_substitute`. Only green proofs are read: a red is not here (`failed:*` answered above)."""
    unproven = [(unit, _unit_state(unit)) for unit in _sides_units(manifest, report, cases, cfg)]
    for state in (SIDES_UNKNOWN_STATE, ON_SUBSTITUTE_STATE):
        group = [unit for unit, got in unproven if got == state]
        if group:
            return (state, "; ".join(_unit_words(unit) for unit in group))
    return None


def open_placeholder_rows(manifest: dict) -> dict:
    """PUBLIC (the S5 exit reads it too, AR-13: one predicate of "open", t-2277 J-C9). `{P-n: row}` of the OPEN J-C5 rows of the
    manifest (`contract.first_look_row`, the one predicate): a `placeholder_locator` with
    `assumed_from: first_look:R-n` that is NOT `retracted` and NOT settled (`contract.PROVISIONAL_SETTLED`) with a run block named in
    `evidence.run`. A missing or unreadable status and `settled_*` without `evidence.run` read OPEN (FL-7 adversarial inputs, AR-28: what
    cannot be shown settled is not settled). `kept_by_decision` is NOT open on any side, a real one included (owner word W3, 11.11.2026:
    what the person decided to keep stays kept; the report marks it `on a mock: ... kept by the person's decision`)."""
    out = {}
    for row in C.manifest_provisional(manifest)["rows"]:
        if not C.first_look_row(row):
            continue
        status = str(row.get("status") or "")
        evidence = row.get("evidence") if isinstance(row.get("evidence"), dict) else {}
        if status in ("retracted", "kept_by_decision") or (status in C.PROVISIONAL_SETTLED and str(evidence.get("run") or "").strip()):
            continue
        out[C.provisional_id(row)] = row
    return out


def _placeholder_units(manifest: dict, report: dict, cases: list, cfg) -> list:
    """`[{label, case, then, ids}]` - the units whose green is not a proof because it rests on an open J-C5 row (J-C7); `ids` are the
    P-n named. Two triggers: (1) a Then of `cases` named in an open row's `dependents` (`[{case, then}]`), whatever test covers it and
    whether or not any ran; (2) a Then outside every open row's `dependents` (or a case with no covered Then at all) that no CLEAN
    green proves - a clean proof is a green row joined to a test whose `provisional` (`contract.manifest_provisional` `by_test`) names
    no open row - while at least one green proof of it comes from a test that names one. Each proof is read alone: the evidence of
    two tests is never merged (FR-18). A unit with no green proof at all is not this branch's (it stays what the runs say)."""
    opened = open_placeholder_rows(manifest)
    if not opened:
        return []
    by_test = C.manifest_provisional(manifest)["by_test"]
    covered = [b for b in manifest.get("then_bindings") or [] if isinstance(b, dict) and str(b.get("status") or "") == "covered"]
    _, entry_of, index, entry_of_row, run_row_for = _proof_index(manifest, report, cfg)

    def named(entry) -> list:
        return [pid for pid in by_test.get(C.test_instance_id(entry), []) if pid in opened] if isinstance(entry, dict) else []

    units = []
    for case in cases:
        in_dependents = set()
        for pid, row in opened.items():
            for dep in row.get("dependents") if isinstance(row.get("dependents"), list) else []:
                if isinstance(dep, dict) and C.case_matches(str(dep.get("case") or ""), case, cfg=cfg) and C.then_number(dep.get("then")):
                    in_dependents.add((C.then_number(dep.get("then")), pid))
        for number in sorted({n for n, _ in in_dependents}):
            units.append({"label": f"{case} Then {number}", "case": case, "then": number,
                          "ids": sorted({pid for n, pid in in_dependents if n == number})})
        mine = [b for b in covered if C.case_matches(str(b.get("case") or ""), case, cfg=cfg) and C.then_number(b.get("then"))]
        done = {n for n, _ in in_dependents}
        for number in sorted({C.then_number(b.get("then")) for b in mine} - done):
            clean, marked = False, []
            for b in [b for b in mine if C.then_number(b.get("then")) == number]:
                entry = entry_of(str(b.get("instance_id") or "").strip())
                row = run_row_for(entry, index) if entry is not None else None
                if _green(row):
                    clean, marked = (True, marked) if not named(entry) else (clean, marked + named(entry))
            if marked and not clean:
                units.append({"label": f"{case} Then {number}", "case": case, "then": number, "ids": sorted(set(marked))})
        if not mine:
            clean, marked = False, []
            for row in _case_rows(index, case, cfg):
                entry = entry_of_row(row)
                if named(entry):
                    marked += named(entry)
                else:
                    clean = True
            if marked and not clean:
                units.append({"label": case, "case": case, "then": None, "ids": sorted(set(marked))})
    return units


def _placeholder_reading(manifest: dict, report: dict, cases: list, cfg):
    """`(PLACEHOLDER_OPEN_STATE, detail)` when any unit of `cases` rests on an open J-C5 row (`_placeholder_units`), else None. The
    detail names the Then and the row: `TC-1 Then 2: P-3`."""
    units = _placeholder_units(manifest, report, cases, cfg)
    if not units:
        return None
    return (PLACEHOLDER_OPEN_STATE, "; ".join(f"{u['label']}: {', '.join(u['ids'])}" for u in units))


def missed_sides(manifest: dict, report: dict, case: str, cfg=None) -> list:
    """The sides the unproven `on_substitute` units of `case` missed (`_sides_units`, typed: the item's how-line names them, never a
    reader of a row's detail text). `[]` when `case` has no such unit."""
    cfg = C.case_config() if cfg is None else cfg
    sides = []
    for unit in _sides_units(manifest, report, [case], cfg):
        if _unit_state(unit) == ON_SUBSTITUTE_STATE:
            sides += [s for _, _, bad, _ in unit["found"] for s in bad]
    return list(dict.fromkeys(sides))


def proof_readings(manifest: dict, report: dict, cases: list, cfg=None) -> dict:
    """`{(case, then): (state, detail)}` for every Then of `cases` whose green is NOT a proof: `placeholder_open` first, else `sides_unknown`,
    else `on_substitute` (the same order and units `plan_row_state` reads, minus the words above them). THE public reader of the
    proof-strength rule, for the second reader of "this Then is proven" - the trace table (AR-13, AR-15, FR-10): a Then the ledger
    says needs a re-run is never printed `pass`. Whole-case and walked units (no Then) are not keyed here. Never raises over data."""
    cfg = C.case_config() if cfg is None else cfg
    out: dict = {}
    for unit in _placeholder_units(manifest, report, cases, cfg):
        if unit["then"] is not None:
            out[(unit["case"], unit["then"])] = (PLACEHOLDER_OPEN_STATE, f"{unit['label']}: {', '.join(unit['ids'])}")
    for unit in _sides_units(manifest, report, cases, cfg):
        got = _unit_state(unit)
        if got and unit["then"] is not None:
            out.setdefault((unit["case"], unit["then"]), (got, _unit_words(unit)))
    return out


def plan_row_state(row: dict, manifest: dict, report: dict, triage: dict, cases_by_row: dict,
                   open_oracles: dict | None = None) -> tuple:
    """(state, detail) for one plan row. The order of these branches is the contract:
    a decided deferral outranks an execution result, and an unexecuted `automate` row is
    never silently green. An unconfirmed Then (P20) sits after every failure word and before
    `passed_green`: a case with Thens 1-3 green and Then 4 unknown is never green, and a case
    with a failed Then AND an unknown one reads failed. `open_oracles` (`open_oracles()`: {case: {Then:
    resolver reading}}) closes the other door (t-269 F2): a `covered` binding on a Then whose expected
    value the resolver reads `open` or `invalid` is a green run against nothing anybody confirmed, so it
    reads `not_verified:expectation_unconfirmed` too - never `passed_green`. None (a caller that has not
    read the cases) and a case with no `then_oracles` change nothing.

    HF2-3 (3c1), one test that covers several cases and stops at one case's red assert. The reader of "red by the
    requirement" is `acceptance.red_by_requirement` (one call per plan row, the report's current results as the source). For a
    case C, E(C) = the instances red for ANOTHER case's `contradicts_requirement` row (never one red by a row of C itself) that
    the manifest binds to C (`_shadowed`). With E(C) empty - no red, no row, no binding - nothing below changes: the states
    are byte for byte what they were (the empty outcome, AR-23). With E(C) not empty, C is read by its OWN runs (those of
    the instances outside E(C)): a `failed` one still reads `failed:<verdict>`; otherwise, after every failure, flaky,
    partial, error, unconfirmed, skipped, manual and green-open word and BEFORE the hand-off branch, a Then of C that stands
    behind the red reads `not_executed:blocked_by_check` (variant (b): every Then of C on such an instance, blocked or
    covered; the detail is `_behind_words`) - never `failed` (the red is another case's) and never `passed_green`. A
    `contradicts_requirement` row of C reads `failed:<verdict>` when C's own runs failed (FA-7), and
    `not_executed:contradicts_requirement` when they did not.

    HF3-7: a case whose run word is outside the contract's vocabulary (`_unknown_run_word`; a word with no producer) reads `not_executed:the run recorded <word> for this row's cases` - after every failed, flaky, partial and error
    word, before the unconfirmed and skipped words, never `passed_green`."""
    disposition = row.get("disposition", "")
    reason = row.get("reason", "")
    cases = _cases_for_row(row, manifest, cases_by_row)

    red = red_instances(manifest, report)
    cfg_red = C.case_config() if red else None
    blocked = _blocked_rows(manifest, cfg_red, triage, report)
    shadow = _shadowed(manifest, red, blocked, cases, cfg_red)
    unresolved = [(str(u.get("case")), str(u.get("reason") or "")) for u in C.manifest_unresolved(manifest)]
    cfg_u = cfg_red if cfg_red is not None else C.case_config()
    whole_unconfirmed = []
    for case in cases:
        # RD1-2 (S-6, B-357): the row of a case is found by the identity match (`contract.case_matches`), not by raw key
        # equality: `unresolved[]` rows written by 0.7.x carry a bare id, a plan row's case may be `<area>/TC-NNN`. Several
        # rows (different spellings, or the same key twice) can name one case: they are read in the order of the branches
        # below, so the branch the old code would reach FIRST for either reason answers - the last row never wins silently
        # (a dict comprehension did exactly that). One row: nothing changes.
        for r in _reasons_of_case(unresolved, case, cfg_u):
            if r == EXPECTATION_UNCONFIRMED:
                # D2: a whole-case row naming its question is the person's debt, not a stop - it is said
                # AFTER the failure words below, like the per-Then rows (the case did not run against it).
                if case not in whole_unconfirmed:
                    whole_unconfirmed.append(case)
                continue
            if C.unresolved_decided(r):
                return ("deferred_by_decision", f"{case}: {r}")
            if r == "pending_implementation":
                return ("pending_implementation", case)
            if r == "blocked_by_env":
                # only the environment block is superseded by a later terminal result
                # of the same instance. A decided deferral, `impossible` and
                # `pending_implementation` are statements nothing in a run can answer.
                if not C.superseding_terminal_result(report, manifest, cases=[case]):
                    # t-2277 J-C7 / J-C9 (b): an env block is never read in place of `placeholder_open` (a Then behind an open
                    # first-look row is owed its run). A red would have superseded the block above, so `failed:*` is not hidden.
                    held = _placeholder_reading(manifest, report, [case], cfg_u)
                    if held:
                        return held
                    return (f"env_blocked:{_env_owner(report)}", case)
                continue
            if r == "impossible":
                return ("impossible", case)
            if r == C.HANDED_TO_PERSON and C.case_lookup(C.run_results(report), case, cfg_u, exact_wins=False) in ("failed", "fail"):
                # t-305 N8 attempt 2 (F1, P21): an observed failure outranks a hand-off - the case RAN and went red, so
                # the row reads what the run says (`failed:<verdict>` below), never `not_executed:handed_to_person`
                continue
            if r == AC.CONTRADICTS_REQUIREMENT and _status_without_shadow(report, case, shadow, cfg_red) in ("failed", "fail"):
                # FA-7 (A2): a `contradicts_requirement` row of ANY slice with a case that FAILED by its own runs (those
                # outside E(C)) reads what the run says - `failed:<verdict>` below - not `not_executed`. A row whose case
                # did not fail stays `not_executed:contradicts_requirement` (a claimed red nobody executed is no failure).
                continue
            if r == C.HANDED_TO_PERSON:
                # t-2277 J-C7 / J-C9 (c): a hand-off is never read in place of `placeholder_open` (a red already `continue`d above)
                held = _placeholder_reading(manifest, report, [case], cfg_u)
                if held:
                    return held
            return (f"not_executed:{r or 'unresolved'}", case)

    if disposition in ("skip", "unverifiable"):
        # t-2277 J-C7 (FL-7 fix, F3): a skip decision is never read in place of `placeholder_open` when a Then of its cases stands behind
        # an open J-C5 row; a red of those cases still wins (falls through to `failed:*` below, as every other word above it does)
        held = _placeholder_reading(manifest, report, cases, cfg_u)
        red = held and any(C.case_lookup(C.run_results(report), c, cfg_u, exact_wins=False) in ("failed", "fail") for c in cases)
        if held and not red:
            return held
        if not held:
            if disposition == "skip":
                return (f"skipped:{reason or 'no reason given'}", "")
            return (f"skipped:unverifiable — {reason or 'no reason given'}", "")

    impossible = C.run_impossible(report)
    for case in cases:
        # D2-B2 (AR-15): by the identity match (`impossible` keys as the runner wrote them, the plan's case maybe `<area>/TC-NNN`)
        why = C.case_lookup(impossible, case, cfg_u, rollup=False)
        if why is not None:
            return ("impossible", f"{case}: {why}")

    results = C.run_results(report)
    for case in shadow:         # E(C) not empty: the case by its OWN runs (a case with none left has no result, see below)
        own = _status_without_shadow(report, case, shadow, cfg_red)
        # every spelling of the case goes (a bare alias of it must not answer for the runs the shadow took away), then its own word
        for key in [k for k in results if str(k).strip() and C.case_matches(k, case, cfg=cfg_u)]:
            results.pop(key)
        if own:
            results[case] = own
    handed_over = C.manual_human_evidence(report)
    outcomes = []
    # t-305 N8 (Q17 d): a manual-human case WITH an evidence package was handed to the person, and handing is not
    # a pass - the package is what they check against, the checking is theirs. It used to enter `outcomes` as
    # "pass", so a case nobody had looked at read `passed_green` here. It reads `not_executed:handed_to_person` now,
    # the state every other handed case has (`check_delivery.HANDED_LEDGER_STATE`).
    manual_handed = []
    for case in cases:
        word = C.case_lookup(results, case, cfg_u, exact_wins=False)       # D2-B3 Q2: a green bare row never hides a red area row
        if word is not None:
            outcomes.append((case, word))
        elif disposition == "manual-human" and C.case_lookup(handed_over, case, cfg_u, rollup=False) is not None:
            manual_handed.append(case)
    if not outcomes:
        if whole_unconfirmed:
            return (NOT_VERIFIED_UNCONFIRMED, "; ".join(_whole_case_unconfirmed(manifest, cases)))
        if manual_handed:
            held = _placeholder_reading(manifest, report, manual_handed, cfg_u)      # J-C7: a hand-off never reads in its place
            if held:
                return held
            return (HANDED_STATE, "; ".join(f"{c}: {C.case_lookup(handed_over, c, cfg_u, rollup=False)}" for c in manual_handed))
        if shadow:      # no run of its own is left, but its Thens stand behind a red: that is not "no result recorded"
            return (BLOCKED_STATE, "; ".join(_behind_words(manifest, report, red, shadow, blocked, [c for c in cases if c in shadow], cfg_red)))
        if not cases:
            return ("not_executed:no case designed for this row", "")
        if report.get("execution_status") == "env_blocked":
            return (f"env_blocked:{_env_owner(report)}", ", ".join(cases))
        return ("not_executed:no result recorded for this row's cases", ", ".join(cases))

    failed = [c for c, r in outcomes if r in ("failed", "fail")]
    if failed:
        verdict = _verdict_for_cases(failed, manifest, triage, report)
        return (f"failed:{verdict}", ", ".join(failed))
    # t-2277 J-C7 (PC-5 fix round, L1): `not_verified:placeholder_open` - a Then of these cases that an OPEN first-look placeholder row
    # (J-C5) stands behind is not proven by any green. POSITION INVARIANT: right AFTER `failed:*` (a red stays red) and BEFORE flaky,
    # partial, error, the unknown run word, unconfirmed, skipped, the manual hand-off, green-open, deferred, behind-a-red and the Then
    # hand-off words: no skip, hand-off or flaky word is ever read in place of `placeholder_open`. The branches above `failed:*` that
    # a placeholder could hide behind (an unresolved `handed_to_person` / `blocked_by_env` row, the manual hand-off of a case with no
    # run) and a `disposition: skip` / `unverifiable` row ask `_placeholder_reading` themselves before they return (FL-7). The S5
    # exit closes the same doors by J-C9 (b)-(d) (`s5_precheck._sides_placeholders`).
    placeholder = _placeholder_reading(manifest, report, [c for c, _ in outcomes], cfg_u)
    if placeholder:
        return placeholder
    flaky = _unfixed_flaky(cases, manifest, triage, report)
    if flaky:
        return ("not_verified_flaky", ", ".join(flaky))
    partial = [c for c, r in outcomes if r == "partial"]
    if partial:
        return ("partial", ", ".join(partial))
    errors = [c for c, r in outcomes if r == "error"]
    if errors:
        return ("error", ", ".join(errors))
    # HF3-7 (F-5 (b), M3): a case whose run word is outside the contract's vocabulary was not executed as far as anyone can
    # say - the run recorded something nobody reads. AFTER every failure, flaky, partial and error word (a red beside it is
    # never hidden, and a `partial` case beside it stays `partial`) and BEFORE the unconfirmed-expectation and skipped words
    # below: `not_verified:expectation_unconfirmed` does not block delivery (F7), so a case that did not demonstrably run
    # must not be read through it. It can never reach `passed_green` (the unknown never becomes a pass, FR-59).
    odd = [(c, r) for c, r in outcomes if _unknown_run_word(r)]
    if odd:
        words = C.RUN_WORD_JOIN.join(dict.fromkeys(_run_word_text(w) for _, r in odd for w in C.rollup_words(r)))
        return (f"not_executed:the run recorded {words} for this row's cases", ", ".join(c for c, _ in odd))
    cfg = C.case_config() if (open_oracles or any(isinstance(b, dict) and b.get("reason") == EXPECTATION_UNCONFIRMED
                                                  for b in manifest.get("then_bindings") or [])) else None
    pending = [(c, binding) for c in cases for binding in unconfirmed_bindings(manifest, c, cfg)] if cfg is not None else []
    if pending or whole_unconfirmed:
        parts = ([unconfirmed_detail(pending)] if pending else []) + _whole_case_unconfirmed(manifest, cases)
        return (NOT_VERIFIED_UNCONFIRMED, "; ".join(parts))
    skipped = [c for c, r in outcomes if r in ("skipped", "inconclusive", "not_run", "blocked")]
    if skipped:
        return (f"skipped:{ 'inconclusive run' }", ", ".join(skipped))
    if manual_handed:
        return (HANDED_STATE, "; ".join(f"{c}: {C.case_lookup(handed_over, c, cfg_u, rollup=False)}" for c in manual_handed))
    green_open = []
    for case in [c for c, r in outcomes if r in ("passed", "pass")] if open_oracles else []:
        gaps = next((g for key, g in open_oracles.items() if C.case_matches(key, case, cfg=cfg)), {})
        for binding in manifest.get("then_bindings") or []:
            if (isinstance(binding, dict) and str(binding.get("status") or "") == "covered"
                    and isinstance(binding.get("then"), int) and binding.get("then") in gaps and C.case_matches(str(binding.get("case") or ""), case, cfg=cfg)):
                green_open.append((case, binding["then"], gaps[binding["then"]]))
    if green_open:
        return (NOT_VERIFIED_UNCONFIRMED, "; ".join(
            f"{case} Then {then}: {green_on_open_words(oracle)}"
            + (f". Needed: your answer to {oracle['ref']}" if oracle.get("ref") and oracle.get("state") != "invalid" else "")
            for case, then, oracle in green_open))
    # HF2-5 (5a-K2, A1): a Then a person's recorded decision defers (`then_bindings` row, reason `deferred_by_decision:*`)
    # is not proved by the green runs beside it, and says so in the decision's own word: the same state a deferred WHOLE case
    # reads at the top. After every failure, flaky, partial, error, unconfirmed, skipped, manual and green-open word above
    # (an observed red beats a deferral) and BEFORE the blocked and hand-off remainders below, which would otherwise read the
    # case as a Then behind a red or left with its owner and print another sentence over the decision.
    # A row whose `then` reads as none (`contract.then_number` 0) is still a deferral, said by its case alone: the unknown
    # never becomes `passed_green`.
    deferred = [r for r in manifest.get("then_bindings") or [] if isinstance(r, dict)
                and str(r.get("status") or "") != "covered" and C.unresolved_decided(r.get("reason"))
                and any(C.case_matches(str(r.get("case") or ""), c) for c, _ in outcomes)]
    if deferred:
        return ("deferred_by_decision", "; ".join(
            f"{r['case']}" + (f" Then {C.then_number(r.get('then'))}" if C.then_number(r.get("then")) else "") + f": {r['reason']}"
            for r in deferred))
    # HF2-3 (3c1): a Then that stands behind another check's red (E(C), or a `blocked_by_check` row whose blocker no longer
    # reads red: a stale row is not a pass) is not proved by the green runs beside it. After every failure word above and
    # BEFORE the hand-off branch below: the branch can only turn a would-be `passed_green` into the blocked state.
    behind = _behind_words(manifest, report, red, shadow, blocked, [c for c in cases if C.case_lookup(results, c, cfg_u, exact_wins=False) is not None or c in shadow], cfg_red)
    if behind:
        return (BLOCKED_STATE, "; ".join(behind))
    # GW1-14, the LAST check before `passed_green`: a Then the person took (`contract.then_remainders`) is not
    # proved by the green run beside it. Every failure, flaky, partial, error, unconfirmed, skipped, manual and
    # green-open state above wins over this one; the branch can only turn a would-be `passed_green` into the hand-off
    # state, so a red result is never restated as "the person will check" (E7, E16).
    left = [r for r in C.then_remainders(manifest) if any(C.case_matches(r["case"], c) for c, _ in outcomes)]
    if left:
        return (HANDED_STATE, "; ".join(
            f"{r['case']} Then {r['then']}" + (f" ({r['part']})" if r["part"] else "")
            + f": left with {'another environment' if r['owner'] == 'other_environment' else 'the person'}"
            + (f" - {r['detail']}" if r["detail"] else "") + "; its other Thens passed" for r in left))
    # t-2181 §2.3 (PC-5, C9): the proof-strength branch - `sides_unknown` first, then `on_substitute`. POSITION INVARIANT: the LAST
    # check before `passed_green`. The resulting order of the whole function: ... `failed:*` -> `placeholder_open` -> flaky -> partial
    # -> error -> unknown run word -> unconfirmed -> skipped -> manual hand-off -> green-open -> deferred -> behind-a-red -> Then
    # hand-off -> `sides_unknown` -> `on_substitute` -> `passed_green`. What that keeps unreachable: a green on a substituted or unknown
    # side reading `passed_green`; what it keeps refused: a red stays red, and nothing above is restated as `on_substitute` (a red on
    # a substitute stays `failed:*`, a deferral stays `deferred_by_decision`, which is `no`; a Then behind an open placeholder reads
    # `placeholder_open`, not `on_substitute`). A row with no stamp and no non-real declaration is not read at all (E-T1), so an
    # all-real story reads exactly as before.
    sides = _sides_reading(manifest, report, [c for c, _ in outcomes], cfg_u)
    if sides:
        return sides
    return ("passed_green", ", ".join(c for c, _ in outcomes))


def _env_owner(report: dict) -> str:
    """The owner of an environment block that is still in force.

    `current_env_blocked` is the reducer's projection of the rows a later terminal result
    has NOT superseded; `env_blocked` keeps every row ever recorded, including the stale
    ones, so naming an owner from it would put a resolved outage on somebody's desk."""
    blocked = report.get("current_env_blocked")
    if not isinstance(blocked, list):
        blocked = [row for row in report.get("env_blocked") or []
                   if isinstance(row, dict) and not row.get("superseded")]
    for row in blocked:
        if isinstance(row, dict) and row.get("owner"):
            return str(row["owner"])
    return "user"


def superseded_blocks(manifest: dict, report: dict) -> list:
    """Environment blocks a later terminal result of the same instance has answered.

    They stay here — visible, with what superseded them — because a record that decides
    nothing is still evidence of what the stand did that day. Deleting it and ignoring it
    are different things, and only one of them can be reviewed."""
    out = []
    for entry in C.manifest_unresolved(manifest):
        case = str(entry.get("case") or "")
        if str(entry.get("reason") or "") != "blocked_by_env" or not case:
            continue
        later = C.superseding_terminal_result(report, manifest, cases=[case])
        if later:
            out.append({"kind": "manifest_unresolved", "ref": case, "block": "blocked_by_env",
                        "superseded_by": {"instance_id": str(later.get("instance_id") or ""),
                                          "attempt_id": str(later.get("attempt_id") or ""),
                                          "status": C.result_status(later)}})
    for row in report.get("env_blocked") or []:
        if isinstance(row, dict) and row.get("superseded"):
            out.append({"kind": "run_env_blocked",
                        "ref": str(row.get("case") or row.get("instance_id") or row.get("area") or "?"),
                        "block": "env_blocked", "superseded_by": row.get("superseded_by") or {}})
    return out


def _cases_for_row(row: dict, manifest: dict, cases_by_row: dict) -> list:
    """The cases this plan row produced: the case files whose `Plan row:` header names it,
    plus any manifest entry that points at it. A row with no case is a hole, and says so."""
    cases = list(cases_by_row.get(row.get("ts"), []))
    for entry in C.manifest_tests(manifest) + C.manifest_unresolved(manifest):
        if str(entry.get("plan_row") or "") == row.get("ts"):
            for case in C.manifest_test_links(entry):
                # D2-B2: the link is bare (`manifest_test_links` strips the area), a plan case may be `<area>/TC-NNN`: one case
                # by the identity match, not a second bare one (a blank link names nothing: E-B1)
                if case and not C.names_case(cases, case):
                    cases.append(case)
    return cases


def near_triage_row(rows: list, names: list, attempt: str = "", failures: dict | None = None, status: str = ""):
    """The ONE triage row that answers the test `names` stand for, else None - a thin call of
    `contract.triage_row_for` over `contract.bind_triage`, the binding every reader shares (t-323 A1; t-319 had
    named the predicate `same_id` and left each reader its own ladder, so a row `m::x` answered the test
    `m::x[json]` here while gate B called it ambiguous beside `m::x[multi]`).

    `failures` is the run report's (`contract.triage_failures`): without it the test is the only failure the
    binding knows, and a sibling's row is still never its verdict (several rows near one name answer None). INVARIANT:
    a row is never a verdict for a test it did not name; a row that names the test EXACTLY beats the rows that only
    share its base; a row of another attempt than `attempt` (when both are recorded) is not this test's."""
    return C.triage_row_for(failures or {}, [r for r in rows if isinstance(r, dict)], names, attempt, status)


def _triage_row(case: str, entry: dict | None, triage: dict, result: dict | None = None, report: dict | None = None):
    """The triage row for one test, through `near_triage_row`: the names the test answers to are its manifest
    instance id, the id the run report keeps (`file::name`), the manifest's full test id and `file::marker`. Never a
    substring of the file path - ten tests share one file, and one failure must not colour the other nine (live
    run QA-1, 2026-09-11). `case` names the test for the manifest lookup only: a row that carries a case and a test
    is the verdict of THAT test, never of every test of the case (t-323 A1). `report` gives the binding the other
    failures of the run, so a row ambiguous between two of them is the verdict of neither."""
    entry, result = entry or {}, result or {}
    names = [C.test_instance_id(entry), C.result_id(result), str(result.get("instance_id") or ""),
             str(entry.get("test") or ""),
             (str(entry.get("file") or "") + "::" + str(entry.get("marker") or "")) if entry.get("marker") else ""]
    failures, _unnamed = C.triage_failures(report or {})
    return near_triage_row(C.triage_rows(triage), names, str(result.get("attempt_id") or ""), failures,
                           C.result_status(result))


def _verdict_for_cases(cases: list, manifest: dict, triage: dict, report: dict | None = None) -> str:
    entries = {str(t.get("case")): t for t in C.manifest_tests(manifest)}
    cfg = C.case_config()  # once per call, not once per (case, result): B-013 performance
    for case in cases:
        current = next((row for row in C.current_instance_results(report or {}).values()
                        if case in C.case_ids(row.get("case"), cfg=cfg)), None)
        row = _triage_row(case, entries.get(case), triage, current, report)
        if row is not None:
            return str(row.get("verdict") or "untriaged")
    return "untriaged"


def _unfixed_flaky(cases: list, manifest: dict, triage: dict, report: dict | None = None) -> list:
    entries = {str(t.get("case")): t for t in C.manifest_tests(manifest)}
    out = []
    for case in cases:
        row = _triage_row(case, entries.get(case), triage, None, report)
        if row is not None and row.get("verdict") == "FLAKY" and row.get("fix_result") != "fixed":
            out.append(case)
    return out


def verdict_of(entry) -> str:
    """The critic's verdict of a manifest row, stripped: ONE reading for the ledger, the report's
    basis column, the delivery checks and the coverage projection."""
    return str((entry or {}).get("critic_verdict") or "").strip()


def is_unverified(entry) -> bool:
    """The critic could not verify this test (D-0013): the person's debt, never a block."""
    return verdict_of(entry) == UNVERIFIED


def is_rejected(entry) -> bool:
    """The critic rejected this test: the ONE reading of that word (`verdict_of` strips it). `"REJECTED"` is not it - that
    is `review_unrecognised`, a defect of the record (FR-19), never a rejection the critic did not write."""
    return verdict_of(entry) == "rejected"


def test_name(entry: dict) -> str:
    """The test's function as a person names it: the marker, else the function, else the name the instance id carries - never
    the hash itself (FR-6). The ONE spelling `test_label` and `gap_identity` share."""
    entry = entry if isinstance(entry, dict) else {}
    return str(entry.get("marker") or entry.get("test_function") or "").strip() or C.function_name(C.test_instance_id(entry))


def test_label(entry: dict) -> str:
    """The test as a person names it: its file and its function (`tests/a.py::test_x`), never the
    instance hash (FR-6)."""
    entry = entry if isinstance(entry, dict) else {}
    file = str(entry.get("file") or "").strip()
    name = test_name(entry)
    return f"{file}::{name}" if file and name else (file or name or "an unnamed test")


def proof_shown(entry: dict, manifest: dict | None, task_root) -> tuple:
    """(the row's `proof_level`, the words a reader is shown) for one manifest test.

    The level comes from `proof_level.reached` — the ONE reader of receipts (FR-17): the id of the
    best valid receipt; `unknown` when a receipt exists but the test file it should be compared
    with cannot be found (FR-41: not "not probed"); `not_required` for a test nobody asked to be
    probed (unchanged, unmeasured, or handed to the person) with nothing reached; else `None`, a
    required check that is absent. A higher level that is missing never appears here as a gap.

    A not-required row says WHY in words: `PL.words_for(PL.not_required_why(entry, manifest))` - the
    words follow the reason, not the level id (an unchanged and an unmeasured test share today's
    words, a handed one has its own). The reason itself is `proof_reason`."""
    got = PL.reached(entry, manifest, task_root)
    if got["level"]:
        return got["level"], got["words"]
    # `reached()` exposes no "unknown" flag (its result is {level, words, ref, issues}); it says
    # unknown through the vocabulary's own `unknown_words`, so that is what is compared. If
    # proof_level ever gains an explicit flag, read it here instead.
    if got["words"] == PL.unknown_words():
        return PROOF_UNKNOWN, got["words"]
    if not PL.proof_required(entry, manifest):
        return PROOF_NOT_REQUIRED, PL.words_for(PL.not_required_why(entry, manifest))
    return None, got["words"]


def _run_and_triage_rows(entry: dict, report: dict, triage: dict, cfg, manifest: dict | None = None) -> tuple:
    """(the run report's current row of this test, the triage row that answers it) - either may be None. The one
    lookup `test_state` and the S7 debt rows (`triage_words`) share, and the trace table reads the same row:
    `case_stamp.run_row_for` (HF2-6, AR-13) - the instance's own ids, the dashboard's tolerant rule, a bare function's
    parameter rows, and for an entry with no identity of its own the only current row of its case when it is the only live
    entry of that case. `manifest` is what counts the live entries; without it the entry stands alone (the old reading).
    A neighbour's row is never this test's: no row reads `not_executed`, not the green of a sibling of the case."""
    import case_stamp as CS   # lazy: the stamp's own imports must not load with the ledger
    case = str(entry.get("case") or "")
    if manifest is None:
        live = [entry]
    else:
        from traceability import is_dead_test   # lazy: traceability imports this module
        live = [candidate for candidate in C.manifest_tests(manifest) if not is_dead_test(candidate)]
    index = CS.run_rows_index(C.current_instance_results(report), live, cfg)
    current_row = CS.run_row_for(entry, index)
    return current_row, _triage_row(case, entry, triage, current_row, report)


def _row_freshness(entry: dict, current_row, artifacts) -> tuple:
    """`(state, why)` of `proof_level.run_freshness` over the run row `_run_and_triage_rows` returned (HF2-11, AR-28): did that
    run run the code the test holds NOW. It sits HERE, on the row the join returned, and never inside the join (`case_stamp.
    run_row_for` stays one lookup, F-6). No row: `("unknown", "")` - there is no run to be fresh or stale."""
    if not isinstance(current_row, dict) or not current_row:
        return "unknown", ""
    got = PL.run_freshness(entry, current_row, artifacts)
    if got == ("stale", PL.WHY_NO_FILE):
        # a test file that cannot be found under the project is `unknown` HERE, not `stale` (Lead decision, t-129): the
        # ledger is also built over a story whose project root is not the run's, and over fixtures that name no file, so
        # it cannot tell a deleted test from a ledger read elsewhere. Today's reading is kept and the unknown is PRINTED
        # (`test_state` adds " - run freshness not measured: <why>" to a `passed_green`; FR-59), never silent. The window
        # (`proof_level`, 11a) keeps `stale` for a missing file: it runs inside the project.
        return "unknown", PL.WHY_NO_FILE
    return got


def _changed_after_run(freshness: tuple) -> str:
    """The suffix a RED keeps when the test changed after its run: an edit never hides a red (the verdict stays `failed:*`)."""
    state, why = freshness
    return f" (the test changed after this run: {why})" if state == "stale" else ""


def triage_refs(artifacts: Path, row: dict) -> list:
    """The ledger refs (`instance_id`, else `contract.test_instance_id`: the key `_covers` matches an S7 debt window by) of every
    manifest test whose triage row, as `_run_and_triage_rows` finds it, IS `row`. The ONE public reader the S7 repair loop writes a
    debt entry's `tests` by (t-698 §18.4): the ref is not the triage row's own `test` (the ledger spells a contract-shape or a
    parametrized test differently), so only this reading names what the report will match. `[]` when no test is bound to the row."""
    artifacts = Path(artifacts)
    manifest = C.load_json(C.artifact(artifacts, "automation-manifest.json"))
    report = C.load_json(C.artifact(artifacts, "run-report.json"))
    triage = C.load_json(C.artifact(artifacts, "triage.json"))
    cfg = C.case_config(artifacts)
    refs: list = []
    for entry in C.manifest_tests(manifest):
        found = _run_and_triage_rows(entry, report, triage, cfg, manifest)[1]
        ref = str(entry.get("instance_id") or C.test_instance_id(entry))
        if found is not None and found == row and ref not in refs:
            refs.append(ref)
    return refs


# The word `manifest_put.BASE_OUTCOMES` holds for a base that answered with a refusal; `test_ledger.py` pins the two together.
BASE_REFUSED = "refused"
NOT_VERIFIED_REFUSED_BASE = "not_verified:oracle_on_refused_base"


def _refused_base_of_this_run(entry: dict, current_row) -> bool:
    """Is the test's `base_outcome` (the code critic's record, `manifest_put.py --fragment`) a refusal IN THE RUN THE LEDGER READS?
    `run` must equal the `attempt_id` of the run row the join returned: a new run has another attempt id, so a repaired test that
    ran green again leaves this state by itself, with no command (AR-25, FR-40). Anything else (no record, `working`, a word the
    writer refuses, no run id, a row with no attempt id) reads as no record: an unknown is never a verdict (FR-41)."""
    block = entry.get("base_outcome") if isinstance(entry, dict) else None
    if not isinstance(block, dict) or block.get("outcome") != BASE_REFUSED:
        return False
    run = str(block.get("run") or "").strip()
    return bool(run) and run == str((current_row or {}).get("attempt_id") or "").strip()


def test_state(entry: dict, report: dict, triage: dict, artifacts: Path | None = None,
               manifest: dict | None = None) -> tuple:
    """(state, detail) for one manifest test. `manifest` is the manifest the entry belongs to;
    without it nothing is known to be handed to the person (the old behaviour)."""
    test_id = str(entry.get("file") or "") + ("::" + str(entry.get("marker")) if entry.get("marker") else "")
    parameters = C.canonical_parameters(entry.get("parameters") or entry.get("parameter_map"))
    display = test_id + (f" [{', '.join(f'{k}={v}' for k, v in parameters.items())}]" if parameters else "")
    cfg = C.case_config(artifacts)  # once per test, not once per (test, result): B-013 performance
    current_row, row = _run_and_triage_rows(entry, report, triage, cfg, manifest)
    if row is not None:
        verdict = str(row.get("verdict") or "untriaged")
        if verdict == "FLAKY" and row.get("fix_result") != "fixed":
            return ("not_verified_flaky", f"{display} — mechanism {row.get('mechanism') or 'unnamed'}")
        if verdict == "FLAKY":
            if is_rejected(entry):    # RD1-9a: a fixed flake does not outvote the critic's rejection (FR-18)
                return ("review_rejected", display)
            return ("passed_green", f"{display} — flaky root fixed, confirmed by re-runs")
        if verdict == "ENV_ISSUE":
            return (f"env_blocked:{row.get('owner') or 'factory'}", display)
        return (f"failed:{verdict}", display + _changed_after_run(_row_freshness(entry, current_row, artifacts)))
    review = verdict_of(entry)
    if not review:
        return ("review_skipped", display)
    # Each verdict keeps its own word (FR-35): on one run the critic's 19 instances were 11
    # approved, 5 unverified and 3 rejected, and the ledger read all 8 non-approved as
    # `review_rejected` - rejected work is redone, unverified work is only not yet checked.
    if is_rejected(entry):
        return ("review_rejected", display)
    if review not in {"approved", "approved_with_fixes", UNVERIFIED}:
        # A word the vocabulary does not hold is a defect of our own record (FR-19), never a
        # rejection the critic did not write. The backtick would break `check_delivery`'s
        # reading of "is `<state>`", so it goes with the whitespace.
        return (f"review_unrecognised:{_run_word_text(review)}", display)
    # The run result is read BEFORE the verdict can turn a green into a debt: an unverified
    # verdict never hides a run failure (a red, an error, a partial or a test that never ran
    # keeps its own state, D-0013).
    results = C.run_results(report, cfg)
    result = C.result_status(current_row) if current_row else ""
    # HF2-6: the case's summary (`results.get(case)`) is NOT read - a sibling instance of the case that ran green would
    # lend its pass to a test that never ran; the legacy single-row case is `run_row_for`'s fourth step. The test's own id
    # spellings stay (a row of THIS test).
    result = result or results.get(str(entry.get("test") or "")) or results.get(test_id)
    if result in ("failed", "fail"):
        return ("failed:untriaged", display + _changed_after_run(_row_freshness(entry, current_row, artifacts)))
    # HF2-11 (11c): a GREEN of code the test no longer holds is not a pass. Read on the row the join returned, AFTER the red
    # branches (an edit never hides a red) and BEFORE any state that rests on the green (an unverified review, a proof check).
    # `unknown` (the row recorded no per-test identity, a non-pytest runner) keeps today's reading and SAYS so (FR-59).
    freshness = _row_freshness(entry, current_row, artifacts) if result in ("passed", "pass") and current_row else ("unknown", "")
    if freshness[0] == "stale":
        return (CHANGED_STATE, display + " — " + freshness[1])
    if review == UNVERIFIED and result in ("passed", "pass"):
        # The proof was stopped by a tool or the stand, not by the test (D-0013): it blocks
        # neither S5 nor delivery, and the reason the critic gave travels to the person.
        why = " ".join(str(entry.get("sensitivity_proof_missing_reason") or "").split())
        return ("review_unverified", display + (f" — {why}" if why else ""))
    # Verification is an independent axis: only a product green can be downgraded by a
    # missing/invalid proof. A real failure remains visible for triage. An unverified test has
    # no proof to ask for: its debt is the person's, not a missing receipt.
    if review != UNVERIFIED and PL.proof_required(entry, manifest):
        issues = PL.reached(entry, manifest, artifacts)["issues"]
        if issues:
            return ("not_verified:missing_sensitivity_proof", display + " — " + "; ".join(issues))
    # TQ1-18: a GREEN test whose before/after base the code critic read in the run log as a REFUSAL proves nothing about what it is
    # for (the same refusal twice is equal). ONLY a green (`passed`) and ONLY this run's record: a red returned above, a stale run
    # and the proof check above kept their states, and `error`/`partial`/skipped/not-run below keep theirs byte for byte.
    if result in ("passed", "pass") and _refused_base_of_this_run(entry, current_row):
        return (NOT_VERIFIED_REFUSED_BASE, display + " — the base of its before/after comparison was a refusal in this run, "
                "so the equality proves nothing about what the requirement is for")
    if result in ("passed", "pass"):
        return ("passed_green", display + (f" — run freshness not measured: {freshness[1]}" if freshness[0] == "unknown" and freshness[1] else ""))
    if result == "error":
        return ("error", display)
    if result == "partial":
        return ("partial", display)
    if result in ("skipped",):
        return ("skipped:marked skipped in the run", display)
    if report.get("execution_status") == "env_blocked":
        return (f"env_blocked:{_env_owner(report)}", display)
    # HF3-7 (F-5 (b)): the run DID record a word for this test, one the contract does not know - "no result" would be false.
    # AFTER the environment check: a run that was env-blocked keeps the owner of the block, whatever the row says.
    if _unknown_run_word(result):
        return (f"not_executed:the run recorded {_run_word_text(result)} for this test", display)
    return ("not_executed:" + NO_RUN_RESULT, display)


def open_subtasks(context: dict) -> list:
    out = []
    for row in context.get("subtasks") or []:
        if not isinstance(row, dict):
            continue
        if str(row.get("status") or "").strip().lower() not in DONE_SUBTASK_STATUSES:
            out.append({"key": str(row.get("key") or "?"), "status": str(row.get("status") or "")})
    return out


def apply_waiver(entry: dict, row: dict, waivers: dict) -> dict:
    """A plan row every one of whose requirements a person waived is closed by that decision.

    Only when EVERY requirement on the row is covered: a row that also carries an unwaived
    requirement still owes its evidence. The row keeps saying what actually happened —
    `waived:not_executed` — because "waived" and "passed" are different facts and a ledger
    that blurs them is worth nothing at the next gate."""
    if C.ledger_state_prefix(entry.get("state", "")) in ("passed_green", "waived"):
        return entry
    requirements = [str(r) for r in (row.get("requirements") or []) if str(r)]
    governing = [waivers[r] for r in requirements if r in waivers]
    if not requirements or len(governing) != len(requirements):
        return entry
    gates = sorted({str(w.get("gate") or "?") for w in governing})
    reasons = "; ".join(dict.fromkeys(str(w.get("reason") or "").strip() for w in governing if w.get("reason")))
    entry["state"] = "waived:" + str(entry.get("state") or "unknown")
    entry["waived_requirements"] = requirements
    # t-305 N8: the person's own words travel on the row, so the delivery verdict can tell a deferral somebody
    # worded (`deferred_with_words`) from a bare one nobody recorded (`deferred_undecided`) without opening
    # pipeline.json again - and so the Left-with-you item can quote them (FR-8).
    entry["decision"] = [{"gate": str(w.get("gate") or ""), "requirement": str(w.get("requirement") or ""),
                          "words": " ".join(str(w.get("decision") or "").split()), "at": str(w.get("at") or "")}
                         for w in governing]
    entry["detail"] = (f"closed by a gate {'/'.join(gates)} waiver"
                       + (f" — {reasons}" if reasons else "")
                       + f" (what was observed: {entry.get('detail') or 'no detail'})")
    return entry


# --- the repair-limit carrier (C1-5c): work/review-debts.json --------------------------------------------------------
# A window of S5 or S7 that closed over a rejection because its repair limit was spent (or could not be counted, or the
# problem was nobody's to repair) is recorded here by the driver, at the person's answer. The ledger is its ONE reader
# (`read_review_debts`) and this module its ONE writer (`write_review_debt`); the remarks are NOT copied into it - they
# are read from the critic's own form through `repair_route.findings`, so no second copy of the critic's words exists.
REVIEW_DEBTS = "review-debts.json"
DEBT_STAGES = ("S5", "S7")
# `cap` the test_defect cap is spent, `unknown` the controller's count cannot be read, `mech_cap` the mechanical cap is spent,
# `nobody` the blocking findings are nobody's round, `sent_back` the verdict sent the window back naming no blocking finding,
# `untyped` the verdict sent it back with no finding the test writer can act on (a debt file without the word still loads).
DEBT_REASONS = ("cap", "unknown", "mech_cap", "nobody", "sent_back", "untyped")
NOT_RECORDED = "the critic's remarks were not recorded"


def _debt_count(value):
    return value if isinstance(value, int) and not isinstance(value, bool) else None


def _debt_words(value) -> str:
    return " ".join(str(value if value is not None else "").split())


def _debt_list(value) -> list:
    return [_debt_words(item) for item in value if _debt_words(item)] if isinstance(value, list) else []


def debt_entry(raw) -> dict | None:
    """One window of the carrier with every key of the schema present: a key that is absent or of the wrong type reads at its
    null value (`""`, `[]`, `None`) and `debt_missing` names it, so a reader never meets a KeyError and never a made-up value
    (FR-41). None for what is no window: not a dict, or a stage other than S5 / S7."""
    if not isinstance(raw, dict) or _debt_words(raw.get("stage")) not in DEBT_STAGES:
        return None
    rounds = raw.get("rounds") if isinstance(raw.get("rounds"), dict) else {}
    choice = raw.get("choice") if isinstance(raw.get("choice"), dict) else {}
    entry = {"stage": _debt_words(raw.get("stage")), "cases": _debt_list(raw.get("cases")),
             "tests": _debt_list(raw.get("tests")), "critic_dispatch": _debt_words(raw.get("critic_dispatch")),
             "form": _debt_words(raw.get("form")), "reason": _debt_words(raw.get("reason")),
             "rounds": {"counted": _debt_count(rounds.get("counted")), "cap": _debt_count(rounds.get("cap")),
                        "by_cause": rounds.get("by_cause") if isinstance(rounds.get("by_cause"), dict) else {}},
             "choice": {"token": _debt_words(choice.get("token")), "words_file": _debt_words(choice.get("words_file")),
                        "at": _debt_words(choice.get("at"))}}
    if _debt_words(raw.get("fixed_by")):
        entry["fixed_by"] = _debt_words(raw.get("fixed_by"))   # set when a later critic dispatch cleared the window
    return entry


def debt_missing(entry: dict) -> list:
    """The keys of a window the record does not hold, by the name a person can read: `reason`, `rounds` (only where the reason
    is a count), `choice`, and the scope (`cases` at S5, `tests` at S7)."""
    out = []
    if entry["reason"] not in DEBT_REASONS:
        out.append("reason")
    counted = entry["reason"] in ("cap", "mech_cap")
    if counted and (entry["rounds"]["counted"] is None or entry["rounds"]["cap"] is None):
        out.append("rounds")
    if not entry["choice"]["token"]:
        out.append("choice")
    if not entry["tests" if entry["stage"] == "S7" else "cases"]:
        out.append("tests" if entry["stage"] == "S7" else "cases")
    return out


def debt_key(entry: dict) -> tuple:
    """What makes two records ONE window: the stage, the critic dispatch and the scope."""
    return (entry["stage"], entry["critic_dispatch"], tuple(sorted(entry["cases"])), tuple(sorted(entry["tests"])))


def _debt_rows(artifacts: Path) -> tuple:
    """(the raw `windows` list of the carrier, the problem in words): `([], "")` with no file; `(None, problem)` when the file
    cannot be read as a carrier (two copies that differ, not an object, no `windows` list). The ONE place the file is read: the
    reader and the writer both go through it."""
    import hooklib
    try:
        path = C.artifact(artifacts, REVIEW_DEBTS)
    except ValueError:
        return None, "the record of the repair-limit answers exists twice and the two copies differ"
    if not path.is_file():
        return [], ""
    document = hooklib.read_json(path, None, kind=dict)
    rows = document.get("windows") if document else None
    if not isinstance(rows, list):
        return None, "the record of the repair-limit answers cannot be read"
    return rows, ""


def _unreadable_places(rows: list) -> list:
    """The 1-based places in the file of the entries that are no window."""
    return [place for place, raw in enumerate(rows, start=1) if debt_entry(raw) is None]


def read_review_debts(artifacts: Path) -> dict:
    """{"windows": [debt_entry], "problem": str}. No file is no windows and no problem (a story that never reached a limit, or
    one written before this carrier: the ledger reads as it always did). A file that cannot be read, or holds no `windows`
    list, or an entry that is no window, is a `problem` in words - and the report then says it, never silence (FR-41). An
    entry that is no window is named by its place in the file, and the writer keeps it where it stands."""
    rows, problem = _debt_rows(artifacts)
    if rows is None:
        return {"windows": [], "problem": problem}
    lost = _unreadable_places(rows)
    many = len(lost) != 1
    return {"windows": [entry for entry in map(debt_entry, rows) if entry is not None],
            "problem": (f"{len(lost)} {'entries' if many else 'entry'} of the record of the repair-limit answers could not be read "
                        f"(place {', '.join(map(str, lost))} in the file); {'they are kept as they stand' if many else 'it is kept as it stands'}")
            if lost else ""}


def write_review_debt(artifacts: Path, window: dict) -> dict:
    """THE writer of `work/review-debts.json`: the driver calls it at the person's answer to a repair-limit question
    (`debt`), once per window. A window already recorded under the same key (`debt_key`) is replaced, never doubled, so a
    repeated call, a resumed run and a later `fixed_by` stamp leave one entry; the entries of other windows are kept as
    they were, and an entry the reader could not read stays where it is, as it stands (FR-41: what could not be read is never
    overwritten). When NOTHING in the file can be read (it is no carrier, or none of its entries is a window) the file is left
    as it was, one line on stderr names it and the window is not recorded: the function returns None then. A window of another
    stage, or a reason outside DEBT_REASONS, is refused by name (FR-1)."""
    entry = debt_entry(window)
    if entry is None:
        raise ValueError(f"a repair-limit record names the stage S5 or S7, not {window.get('stage') if isinstance(window, dict) else window!r}")
    if entry["reason"] not in DEBT_REASONS:
        raise ValueError(f"a repair-limit record names one reason of {', '.join(DEBT_REASONS)}, not {entry['reason']!r}")
    rows, problem = _debt_rows(artifacts)
    if rows is None or (rows and len(_unreadable_places(rows)) == len(rows)):
        print(f"{REVIEW_DEBTS} is left as it was: {problem or 'none of its entries can be read'}; the window of "
              f"{', '.join(entry['cases'] or entry['tests']) or 'no cases'} is not recorded", file=sys.stderr)
        return None
    kept = []
    for raw in rows:
        old = debt_entry(raw)
        if old is None:
            kept.append(raw)                     # what could not be read stays as it stands
        elif debt_key(old) != debt_key(entry):
            kept.append(old)
    document = {"schema_version": 1, "windows": kept + [entry]}
    atomic_json(C.artifact_write_path(artifacts, REVIEW_DEBTS), document)
    return document


def limit_words(reason: str, counted, cap) -> str:
    """The clause that says why a window's repair rounds ended, in a person's words (no cause token, no `test_defect`, no
    dispatch id: A6). The ONE sentence the delivery check, the ledger and the report share; the report capitalises it."""
    if reason == "cap":
        return (f"repair limit exhausted: {counted} of {cap} rounds about the tests themselves"
                if counted is not None and cap is not None else "repair limit exhausted: the number of rounds is not recorded")
    if reason == "unknown":
        return "the factory could not count its repair rounds"
    if reason == "mech_cap":
        return (f"repair limit exhausted: {counted} of {cap} rounds about the technical problems of the tests"
                if counted is not None and cap is not None else "repair limit exhausted: the number of rounds is not recorded")
    if reason == "nobody":
        return "no repair round could be run: what the critic named is not the test writer's to fix"
    if reason == "sent_back":
        return "the critic sent the tests back without naming a blocking finding"
    if reason == "untyped":
        return "the critic sent the tests back without writing a finding the test writer can act on"
    return "the repair limit is recorded without a reason"


def _same_file(left, right) -> bool:
    """Two repo-relative paths as one test and one finding spell them: the same file when they agree after the slash and
    a leading `./` are normalised (a finding of the critic and a manifest row are written by different hands)."""
    def norm(value):
        text = _debt_words(value).replace("\\", "/")
        return text[2:] if text.startswith("./") else text
    return bool(norm(left)) and norm(left) == norm(right)


def _covers(window: dict, entry: dict, ref: str, cfg) -> bool:
    """Does this window speak for this manifest test? S7 windows name instances; S5 windows name cases, matched the way
    every ledger reader matches a case (a bare id and an `<area>/<id>` key are one case)."""
    if window["stage"] == "S7":
        return ref in window["tests"]
    cases = set(C.manifest_test_links(entry, cfg)) | {str(entry.get("case") or "")}
    return any(C.case_matches(key, case, cfg=cfg) for key in window["cases"] for case in cases if case)


def triage_words(entry: dict, report: dict, triage: dict, cfg) -> str:
    """The S7 debt row's wording: what the run says failed, under its own name - `results[].reason` of the run report
    (artifact-contract-run.md); a triage row carries no reason, so none is read from it. A failure whose run recorded no reason
    says so (FR-41) - it never borrows the critic's remarks, which an S7 window does not have."""
    current, _row = _run_and_triage_rows(entry, report, triage, cfg)
    said = _debt_words((current or {}).get("reason"))
    return f"the run failed; the run's reason: {said}" if said else "the run failed; the run recorded no reason"


def _window_remarks(artifacts: Path, window: dict) -> list:
    """The critic's findings of the window, read from the form the record names through `repair_route.findings` (the one reader
    of the form). No form named, a path leaving the story, an absent or unreadable form: no remarks - and the report says
    they were not recorded (edge 7.1), it does not print an empty list."""
    rel = window["form"]
    if window["stage"] != "S5" or not rel or Path(rel).is_absolute() or ".." in Path(rel).parts:
        return []
    import repair_route
    form = repair_route.read_form(Path(artifacts) / rel)
    return repair_route.findings(form) if form is not None else []


def _remark_row(finding: dict) -> dict:
    """The five keys of a finding the ledger keeps (the form stays the one home of the rest)."""
    return {key: finding[key] for key in ("id", "problem", "expected", "fix", "cause")}


def remarks_carrier(artifacts: Path, case: str) -> str:
    """The story-relative path of the critic's findings file that names this case as a whole word (`TC-1` is not `TC-12`), else
    "" - the report then keeps its plain "not recorded" words (FR-41). The file is pointed to, never parsed into rows (TQ1-23).
    Never raises."""
    import re
    case = str(case or "").strip()
    if not case:
        return ""
    pattern = re.compile(r"(?<![\w-])" + re.escape(case) + r"(?![\w-])")
    try:
        root = Path(artifacts)
        import findings_path
        for path in findings_path.all_files(root):
            if pattern.search(path.read_text(encoding="utf-8", errors="replace")):
                return path.relative_to(root).as_posix()
    except OSError:
        return ""
    return ""


def remarks_words(row: dict) -> str:
    """What a rejected row with no remark says in the ledger and in the report: where the critic's words are when a findings
    file names the case, else that they were not recorded. ONE spelling for `render` and `report_facts`."""
    carrier = str((row or {}).get("remarks_carrier") or "").strip()
    return f"the critic's remarks are in {carrier}" if carrier else NOT_RECORDED


def gap_identity(entry: dict) -> dict:
    """What a person calls a rejected test: its function and its case (never the instance hash, FR-6)."""
    links = C.manifest_test_links(entry)
    case = str(links[0] if links else entry.get("case") or "")
    function = test_name(entry) or str(entry.get("file") or "")
    return {"function": function, "case": C.split_case_key(case)[1] or case}


def _holds_a_debt(row: dict) -> bool:
    return C.ledger_state_prefix(row.get("state", "")) in ("review_rejected", "failed")


def attach_review_debts(rows: list, entries: dict, artifacts: Path, triage: dict, report: dict) -> dict:
    """Mark the rows the carrier's windows cover and summarise each window for the report. `entries` is {test row ref: manifest
    entry}. A covered row that still holds its rejection or failure gets `repair_limit` {stage, counted, cap, reason}, and
    `remarks` (S5: the findings whose `file` is the test's manifest `file`) or `triage_words` (S7); a finding that matches no
    such test goes to the window's own `remarks`. A window none of whose tests holds a rejection any more is `fixed` (a later
    review cleared it). Returns {"windows": [...], "problem": str}. Every rejected test row, covered or not, is named by its
    `function` and `case`; with no carrier nothing else is added to the rows. A window covers a row in any open state
    (`review_rejected`, `failed`, `failed:<triage>`), a delinked one included, so the critic's words stay on the row after the
    test later ran."""
    found = read_review_debts(artifacts)
    cfg = C.case_config(artifacts)
    for row in rows:    # a rejected test is named the same way whether a window covers it or not (M2's detector reads that)
        if row.get("kind") == "test" and row.get("ref") in entries and C.ledger_state_prefix(row.get("state", "")) == "review_rejected":
            row.update(gap_identity(entries[row["ref"]]))
    summary = []
    for window in found["windows"]:
        remarks = _window_remarks(artifacts, window)
        covered = [row for row in rows if row.get("kind") == "test" and row.get("ref") in entries
                   and _covers(window, entries[row["ref"]], row["ref"], cfg)]
        holding = [row for row in covered if _holds_a_debt(row)]
        matched = set()
        for row in holding:
            entry = entries[row["ref"]]
            row["repair_limit"] = {"stage": window["stage"], "counted": window["rounds"]["counted"],
                                   "cap": window["rounds"]["cap"], "reason": window["reason"]}
            row.update(gap_identity(entry))
            if window["stage"] == "S7":
                row["triage_words"] = triage_words(entry, report, triage, cfg)
                continue
            mine = [r for r in remarks if _same_file(r["file"], entry.get("file"))]
            matched.update(r["id"] for r in mine)
            row["remarks"] = [_remark_row(r) for r in mine]
        summary.append({"stage": window["stage"], "cases": window["cases"], "tests": window["tests"],
                        "reason": window["reason"], "counted": window["rounds"]["counted"], "cap": window["rounds"]["cap"],
                        "token": window["choice"]["token"], "at": window["choice"]["at"],
                        "refs": [row["ref"] for row in holding], "fixed": bool(covered) and not holding,
                        "fixed_by": window.get("fixed_by", ""), "missing": debt_missing(window),
                        "remarks": [_remark_row(r) for r in remarks if r["id"] not in matched]})
    for row in rows:    # a rejected test no window spoke for: the findings file that names its case, if there is one (RD1-9a)
        if row.get("kind") == "test" and row.get("ref") in entries and not row.get("remarks") \
                and C.ledger_state_prefix(row.get("state", "")) == "review_rejected":
            carrier = remarks_carrier(artifacts, row.get("case"))
            if carrier:
                row["remarks_carrier"] = carrier
    return {"windows": summary, "problem": found["problem"]}


def build(artifacts: Path) -> dict:
    artifacts = Path(artifacts)
    plan_rows = C.parse_plan(C.artifact(artifacts, "test-plan.md"))
    manifest = C.load_json(C.artifact(artifacts, "automation-manifest.json"))
    report = C.load_json(C.artifact(artifacts, "run-report.json"))
    triage = C.load_json(C.artifact(artifacts, "triage.json"))
    context = C.load_json(C.artifact(artifacts, "context-manifest.json"))
    pipeline = C.load_json(artifacts / "pipeline.json")

    cases = C.case_index(artifacts)
    cases_by_row: dict = {}
    for cid, meta in cases.items():
        if meta.get("plan_row"):
            cases_by_row.setdefault(meta["plan_row"], []).append(cid)

    waivers = C.waivers_by_requirement(pipeline)
    rows = []
    test_entries: dict = {}
    gaps = open_oracles(artifacts, cases)     # the ONE resolver's reading of every Then (t-269 F2)
    for row in plan_rows:
        state, detail = plan_row_state(row, manifest, report, triage, cases_by_row, gaps)
        entry = {"ref": row["ts"], "kind": "plan_row", "state": state, "detail": detail}
        rows.append(apply_waiver(entry, row, waivers))
    from traceability import is_dead_test
    try:        # t-2277 W3: the one join of a run row to its test (`_proof_index`) and the provisional rows, read once for the whole loop
        _, _, run_index, _, run_row_for = _proof_index(manifest, report, C.case_config(artifacts))
        provisional = C.manifest_provisional(manifest)
    except Exception:
        run_index = run_row_for = provisional = None
    for entry in C.manifest_tests(manifest):
        state, detail = test_state(entry, report, triage, artifacts, manifest)
        level, level_words = proof_shown(entry, manifest, artifacts)
        row = {"ref": str(entry.get("instance_id") or C.test_instance_id(entry)),
               "kind": "test", "state": state, "detail": detail,
               "proof_level": level, "proof_words": level_words,
               # Why no live check is demanded of this test (`unchanged|handed|unmeasured`, `""` when
               # one is): a fact about the demand, kept apart from the level the receipts reached.
               "proof_reason": PL.not_required_why(entry, manifest)}
        # t-2277 W3: real code or a mock, per test, from existing data (the stamp of its run row, its `sides`, the kept rows). A reading that
        # raised is NOT established, never `real code` (AR-28).
        try:
            row["real_or_mock"] = real_or_mock(entry, run_row_for(entry, run_index), provisional)
        except Exception:
            row["real_or_mock"] = REAL_OR_MOCK_UNKNOWN
        # A delinked aggregate stays in the ledger (its state is still a fact about the run)
        # and stays out of the rendered table: on TP1-15045 six of them reached the
        # person as six separate `review_rejected` lines about tests nobody had written.
        if is_dead_test(entry):
            row["dead"] = True
        rows.append(row)
        test_entries[row["ref"]] = entry

    subtasks = open_subtasks(context)
    for sub in subtasks:
        rows.append({"ref": sub["key"], "kind": "plan_row", "state": "subtask_in_progress",
                     "detail": f"status {sub['status']} at S1 — not closed by this story"})

    review_skipped = any(not t.get("critic_verdict") for t in C.manifest_tests(manifest))
    # the windows that closed over a rejection because their repair limit was spent (C1-5c): the rows they cover carry
    # the critic's remarks, and each window is summarised once for the report (`repair_windows`)
    debts = attach_review_debts(rows, test_entries, artifacts, triage, report)

    from coverage_contract import coverage_projection
    coverage = coverage_projection(artifacts, report, manifest)
    from manual_evidence import export_records
    import manual_evidence as manual_evidence_module
    from coverage_contract import validate_manual_current
    manual_evidence = export_records(artifacts, [r for r in report.get("current_manual_checks", [])
                                               if r.get("schema_version") == 2 and r.get("evidence_validated")
                                               and not validate_manual_current(artifacts, r)])
    previous = C.load_json(C.artifact(artifacts, "ledger.json"))
    from ledger_fingerprint import snapshot as ledger_input_snapshot
    import delivery_verdict as DV
    # t-305 N8: the word travels with the bool. A ledger written before the word existed is read through the ONE
    # reader (`yes` <=> True, else `no`) and a word that disagrees with its bool is not carried (`no`): the error
    # is only ever toward `no`, and `check_delivery` decides the word again on its next run.
    word = DV.word_of(previous)
    word = word if word in DV.WORDS else "no"
    return {
        "ticket": pipeline.get("ticket") or artifacts.name,
        "generated": datetime.now(timezone.utc).isoformat(timespec="seconds"),
        "rows": rows,
        "delivery_ready": word == "yes",
        "delivery_verdict": word,
        "left_items": previous.get("left_items", []) if isinstance(previous.get("left_items"), list) else [],
        "reasons": previous.get("reasons", []),
        "reason_records": previous.get("reason_records", []),
        # Which owners still hold something — `[]` when nothing blocks. The gate-B message
        # and the brief read this field instead of guessing from prose.
        "blocked_by": previous.get("blocked_by", []),
        "superseded_blocks": superseded_blocks(manifest, report),
        "coverage": coverage,
        "manual_evidence": manual_evidence,
        # F5(e) 3: the walks the factory failed to prepare, under their own name; read by `check_delivery.unprepared_records`.
        # Never exported as proof - the filter above keeps them out (no `evidence_validated`)
        "unprepared_walks": manual_evidence_module.unprepared_rows(report),
        "subtasks_open": subtasks,
        "review_skipped": review_skipped,
        "repair_windows": debts["windows"],
        "repair_windows_problem": debts["problem"],
        "source_inputs": ledger_input_snapshot(artifacts),
    }


STALE_DETAIL_PREFIX = "STALE"
# A detail longer than this is a paragraph, not a cell. On TP1-15045 one decision
# paragraph of ~900 characters stood in eleven rows of this table; the person read it eleven
# times and still had to scroll past it to find the next row.
DETAIL_INLINE_MAX = 60


def table_rows(ledger: dict) -> list:
    """The rows a person is shown: everything except the records the factory itself left
    behind — a delinked duplicate and a row its own writer marked STALE decide nothing, and a
    reader cannot tell that by looking."""
    out = []
    for row in ledger.get("rows") or []:
        if row.get("dead"):
            continue
        if str(row.get("detail") or "").lstrip().startswith(STALE_DETAIL_PREFIX):
            continue
        out.append(row)
    return out


def split_detail(detail: str) -> tuple:
    """(what this row is about, the long text behind it). The head is the case key, the
    partition or the test id; everything after the first `: ` is the explanation, and an
    explanation repeated across rows belongs under the table exactly once."""
    text = " ".join(str(detail or "").split())
    head, sep, tail = text.partition(": ")
    if sep and len(head) <= 40 and tail:
        return (head, tail)
    if len(text) > DETAIL_INLINE_MAX:
        return ("", text)
    return (text, "")


def render(ledger: dict) -> str:
    lines = [f"# {ledger.get('ticket', '?')} — checks ledger", "",
             "| Ref | Kind | State | Detail |", "|---|---|---|---|"]
    footnotes: list = []
    for row in table_rows(ledger):
        head, long = split_detail(row.get("detail"))
        if long:
            if long not in footnotes:
                footnotes.append(long)
            head = (head + " " if head else "") + f"[{footnotes.index(long) + 1}]"
        # A green test says how sure we are its check works (D-0010/D-0012), in the level's own
        # words; a legacy ledger carries no `proof_words` and its cell stays as it was.
        if row.get("kind") == "test" and C.ledger_state_prefix(row.get("state", "")) == "passed_green" \
                and row.get("proof_words"):
            head = (head + "; " if head else "") + str(row["proof_words"])
        # M2's failure detector (A8): a rejected test with no remark of the critic's on its row - no window covers it, or the
        # window's form was absent - says so; the line is never left blank
        if C.ledger_state_prefix(row.get("state", "")) == "review_rejected" and not row.get("remarks"):
            head = (head + "; " if head else "") + remarks_words(row)
        detail = head.replace("|", "\\|")
        lines.append(f"| {row.get('ref')} | {row.get('kind')} | `{row.get('state')}` | {detail} |")
    if footnotes:
        lines.append("")
        lines.extend(f"[{index}] {text}".replace("|", "\\|")
                     for index, text in enumerate(footnotes, start=1))
    if ledger.get("coverage", {}).get("obligations"):
        lines.extend(["", "## Behavior evidence", "", "| Obligation | Design | Execution | Verified | Gap |", "|---|---|---|---|---|"])
        for ob in ledger["coverage"]["obligations"]:
            lines.append("| " + " | ".join(str(ob.get(k, "")).replace("|", "\\|") for k in
                ("obligation_id", "design_assessment", "execution_state", "verified", "gap")) + " |")
    if ledger.get("manual_evidence", {}).get("rows"):
        lines.extend(["", "## Manual evidence", ""])
        # This file is delivered and pasted into the gate B packet: it carries no link and no path of a screenshot (the owner's
        # word 31.10.2026: screenshots are the person's, never in the repository). It says what the report says, in the report's
        # words (`grammar.shots_words`, the one writer); a row is in this table only because its export just succeeded, so the
        # pictures it names are provided. The paths go to the person in chat and at gate B (`report_facts.screenshot_groups`).
        import grammar as G
        for row in ledger["manual_evidence"]["rows"]:
            taken = sum(1 for ref in row["evidence_refs"] if isinstance(ref, dict) and G.is_image(ref.get("path")))
            lines.append("- " + str(row.get("case")) + ": " + str(row.get("result")) + " — expected: " + str(row.get("expected", "")).replace("\n", " ") + "; actual: " + str(row.get("actual", "")).replace("\n", " ") + " — " + G.shots_words(taken, taken))
    if ledger.get("superseded_blocks"):
        lines.extend(["", "## Superseded environment blocks", "",
                      "Recorded, then answered by a later run of the same instance. Kept as history; "
                      "they decide nothing here.", ""])
        for row in ledger["superseded_blocks"]:
            by = row.get("superseded_by") or {}
            lines.append("- " + str(row.get("ref")) + " — `" + str(row.get("block")) + "` "
                         + "superseded by " + (str(by.get("status") or "a later attempt"))
                         + " of " + (str(by.get("instance_id") or "the same instance"))
                         + (" (attempt " + str(by["attempt_id"]) + ")" if by.get("attempt_id") else ""))
    lines.append("")
    import delivery_verdict as DV
    # the word the report's verdict block prints (FR-10: one carrier); a ledger with no bool at all reads `no`
    lines.append(f"`delivery_ready: {DV.word_of(ledger) or 'no'}`")
    lines.extend(render_reasons(ledger))
    lines.extend(render_person_debts(ledger))
    return "\n".join(lines) + "\n"


# `contract.DELIVERY_REASON_OWNERS` in reading order: what the person can act on first,
# our own defects last. Splitting them is the whole point — a person cannot act on
# a list that mixes "the product is not proven" with "our reducer could not join two of its
# own records", and reading order is part of the split.
OWNER_ORDER = ("product", "environment", "review", "factory")
OWNER_HEADINGS = {
    "product": "What blocks delivery on the product side",
    "environment": "Environment blockers",
    "review": "Review gaps",
    "factory": "Factory defects (not the product's — nothing is wanted from you)",
}


def reasons_by_owner(ledger: dict) -> dict:
    """reason text per owner, in OWNER_ORDER. Legacy ledgers with no `reason_records` keep
    working: their reasons are shown as `product`, which is how they already read."""
    records = ledger.get("reason_records") or []
    grouped: dict = {}
    if records:
        for record in records:
            if not isinstance(record, dict):
                continue
            owner = str(record.get("owner") or "product")
            owner = owner if owner in C.DELIVERY_REASON_OWNERS else "product"
            grouped.setdefault(owner, []).append(str(record.get("detail") or ""))
    else:
        for reason in ledger.get("reasons") or []:
            grouped.setdefault("product", []).append(str(reason))
    return {owner: grouped[owner] for owner in OWNER_ORDER if grouped.get(owner)}


def person_debts(ledger: dict) -> list:
    """`[{ref, state, detail}]` - the rows that wait for the person's word and hold nothing (F7, P20):
    a Then whose expected value nobody confirmed. They are NOT `reasons` (a reason holds
    `delivery_ready`); they are listed beside them, under the person's name, so the answer that is
    wanted is stated in the task's own terms (FR-20) and the gap is neither hidden nor a block."""
    return [{"ref": row.get("ref"), "state": row.get("state"), "detail": row.get("detail")}
            for row in table_rows(ledger) if row.get("state") == NOT_VERIFIED_UNCONFIRMED]


def render_person_debts(ledger: dict) -> list:
    debts = person_debts(ledger)
    if not debts:
        return []
    lines = ["", "**Left with you (nothing blocks on it)**", ""]
    lines.extend(f"- {debt['ref']}: {debt['detail']}" for debt in debts)
    return lines


# RD1-21: the typed code of a `coverage:` reason - an obligation the factory's tools or coverage left without sufficient
# evidence (owner `factory`). ONE literal: `check_delivery.REASON_CODES` reads it from here.
COVERAGE_GAP_CODE = "COVERAGE_EVIDENCE_GAP"


def factory_coverage_gaps(ledger: dict) -> int:
    """How many reason records are a behaviour no test proves because of the factory's tools or coverage: owner `factory`
    and the coverage code. Those stay unproven, so the sentence "nothing here says the product is not ready" is never
    printed over them (AR-15: every such sentence asks this ONE count). A record that is not an object is skipped."""
    return sum(1 for record in ledger.get("reason_records") or []
               if isinstance(record, dict) and record.get("owner") == "factory" and record.get("code") == COVERAGE_GAP_CODE)


def factory_coverage_line(count: int) -> str:
    return f"{count} behaviour(s) no test proves because of the factory's tools or coverage; they stay unproven"


def render_reasons(ledger: dict) -> list:
    grouped = reasons_by_owner(ledger)
    if not grouped:
        return []
    lines = []
    unproven = factory_coverage_gaps(ledger)
    for owner, reasons in grouped.items():
        lines.extend(["", f"**{OWNER_HEADINGS[owner]}**", ""])
        if owner == "factory" and unproven:
            lines.append("- " + factory_coverage_line(unproven))
        lines.extend("- " + reason for reason in reasons)
    if list(grouped) == ["factory"] and not unproven:
        lines.extend(["", "Nothing here says the product is not ready: every reason left is a defect "
                      "of the factory itself, and it is ours to fix."])
    return lines


def write(artifacts: Path, ledger: dict) -> None:
    """Both files go under `work/`: they are inputs to `test-report.md`, not documents a
    person opens. The rendered table still exists (the report quotes it verbatim, and the
    validator compares them byte for byte) — it just stopped being a fifth thing in the
    human's folder saying what the report already says."""
    artifacts = Path(artifacts)
    work = C.artifact_write_path(artifacts, "ledger.json").parent
    work.mkdir(parents=True, exist_ok=True)
    atomic_json(Path(artifacts) / "evidence" / "index.json", ledger.get("manual_evidence", {"rows": [], "errors": []}))
    atomic_json(work / "ledger.json", ledger)
    markdown = work / "ledger.md"
    temporary = markdown.with_name(markdown.name + ".tmp")
    try:
        temporary.write_text(render(ledger), encoding="utf-8")
        os.replace(temporary, markdown)
    finally:
        temporary.unlink(missing_ok=True)
    from delivery_summary import write as write_delivery_summary
    write_delivery_summary(artifacts, ledger)


def main() -> None:
    C.force_utf8()
    ap = argparse.ArgumentParser(description="Generate the checks ledger")
    ap.add_argument("artifacts", help="qa-factory/artifacts/<TICKET>/")
    ap.add_argument("--json", action="store_true", help="print ledger.json to stdout")
    ap.add_argument("--print", dest="show", action="store_true", help="print the markdown table")
    args = ap.parse_args()

    artifacts = Path(args.artifacts)
    if not artifacts.exists():
        print(f"no such artifacts directory: {artifacts}", file=sys.stderr)
        sys.exit(1)
    ledger = build(artifacts)
    write(artifacts, ledger)
    if args.json:
        print(json.dumps(ledger, ensure_ascii=False, indent=2))
    elif args.show:
        print(render(ledger), end="")
    else:
        print(f"ledger: {len(ledger['rows'])} rows -> {artifacts / C.WORK_DIR / 'ledger.json'}, "
              f"{artifacts / C.WORK_DIR / 'ledger.md'}")
    sys.exit(0)


if __name__ == "__main__":
    main()
